# Dibuat otomatis oleh build.py — jangan diedit manual.
TEMPLATES = {
    '_error_body.html': '<section class="error-page" aria-labelledby="error-title">\n  <p class="error-code" aria-hidden="true">{{ code }}</p>\n  <h1 id="error-title">{{ title }}</h1>\n  <p>{{ message }}</p>\n  <div class="error-actions">\n    {% if g.user %}\n      <a class="btn btn--primary" href="{{ url_for(\'dashboard\') }}">Kembali ke beranda</a>\n    {% else %}\n      <a class="btn btn--primary" href="{{ url_for(\'login\') }}">Kembali ke halaman masuk</a>\n    {% endif %}\n  </div>\n</section>\n',
    '_icons.html': '{% macro icon(name, size=20, cls=\'\') -%}\n<svg class="icon {{ cls }}" width="{{ size }}" height="{{ size }}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">\n  {%- if name == \'home\' -%}\n    <path d="M3 10.5 12 3l9 7.5"/><path d="M5 9.5V21h14V9.5"/><path d="M9.5 21v-6h5v6"/>\n  {%- elif name == \'building\' -%}\n    <rect x="4" y="3" width="16" height="18" rx="1.5"/><path d="M9 7h.01M15 7h.01M9 11h.01M15 11h.01M9 15h.01M15 15h.01M10 21v-3h4v3"/>\n  {%- elif name == \'calendar\' -%}\n    <rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4M16 3v4M3 10h18"/>\n  {%- elif name == \'clock\' -%}\n    <circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>\n  {%- elif name == \'plus\' -%}\n    <path d="M12 5v14M5 12h14"/>\n  {%- elif name == \'check\' -%}\n    <path d="m5 12 4 4L19 6"/>\n  {%- elif name == \'x\' -%}\n    <path d="M6 6l12 12M18 6 6 18"/>\n  {%- elif name == \'alert\' -%}\n    <path d="M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4M12 17h.01"/>\n  {%- elif name == \'info\' -%}\n    <circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 8h.01"/>\n  {%- elif name == \'search\' -%}\n    <circle cx="11" cy="11" r="7"/><path d="m20 20-3.2-3.2"/>\n  {%- elif name == \'arrow-right\' -%}\n    <path d="M5 12h14M13 6l6 6-6 6"/>\n  {%- elif name == \'arrow-left\' -%}\n    <path d="M19 12H5M11 18l-6-6 6-6"/>\n  {%- elif name == \'bell\' -%}\n    <path d="M18 8a6 6 0 0 0-12 0c0 7-3 8-3 8h18s-3-1-3-8"/><path d="M10.3 21a2 2 0 0 0 3.4 0"/>\n  {%- elif name == \'logout\' -%}\n    <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="M16 17l5-5-5-5M21 12H9"/>\n  {%- elif name == \'lock\' -%}\n    <rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/><path d="M12 15v2"/>\n  {%- elif name == \'user\' -%}\n    <circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>\n  {%- elif name == \'users\' -%}\n    <circle cx="9" cy="8" r="3.5"/><path d="M2.5 21a6.5 6.5 0 0 1 13 0"/><path d="M16 5.2a3.5 3.5 0 0 1 0 5.6M18 14.2a6.5 6.5 0 0 1 3.5 6.8"/>\n  {%- elif name == \'grid\' -%}\n    <rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>\n  {%- elif name == \'list\' -%}\n    <path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>\n  {%- elif name == \'settings\' -%}\n    <circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1a2 2 0 1 1-2.8 2.8l-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.5V21a2 2 0 1 1-4 0v-.1a1.7 1.7 0 0 0-1.1-1.5 1.7 1.7 0 0 0-1.9.3l-.1.1a2 2 0 1 1-2.8-2.8l.1-.1a1.7 1.7 0 0 0 .3-1.9 1.7 1.7 0 0 0-1.5-1H3a2 2 0 1 1 0-4h.1A1.7 1.7 0 0 0 4.6 9a1.7 1.7 0 0 0-.3-1.9l-.1-.1a2 2 0 1 1 2.8-2.8l.1.1a1.7 1.7 0 0 0 1.9.3H9a1.7 1.7 0 0 0 1-1.5V3a2 2 0 1 1 4 0v.1a1.7 1.7 0 0 0 1 1.5 1.7 1.7 0 0 0 1.9-.3l.1-.1a2 2 0 1 1 2.8 2.8l-.1.1a1.7 1.7 0 0 0-.3 1.9V9a1.7 1.7 0 0 0 1.5 1H21a2 2 0 1 1 0 4h-.1a1.7 1.7 0 0 0-1.5 1Z"/>\n  {%- elif name == \'door\' -%}\n    <path d="M4 21h16"/><path d="M6 21V4a1 1 0 0 1 1-1h10a1 1 0 0 1 1 1v17"/><path d="M14 12h.01"/>\n  {%- elif name == \'chevron-left\' -%}\n    <path d="m15 18-6-6 6-6"/>\n  {%- elif name == \'chevron-right\' -%}\n    <path d="m9 18 6-6-6-6"/>\n  {%- elif name == \'chevron-down\' -%}\n    <path d="m6 9 6 6 6-6"/>\n  {%- elif name == \'map-pin\' -%}\n    <path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="3"/>\n  {%- elif name == \'filter\' -%}\n    <path d="M3 5h18l-7 8v6l-4 2v-8Z"/>\n  {%- elif name == \'shield\' -%}\n    <path d="M12 3 5 6v6c0 5 3.5 7.5 7 9 3.5-1.5 7-4 7-9V6Z"/><path d="m9 12 2 2 4-4"/>\n  {%- elif name == \'file\' -%}\n    <path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9Z"/><path d="M14 3v6h6M8 13h8M8 17h5"/>\n  {%- elif name == \'check-circle\' -%}\n    <circle cx="12" cy="12" r="9"/><path d="m8 12 2.5 2.5L16 9"/>\n  {%- elif name == \'x-circle\' -%}\n    <circle cx="12" cy="12" r="9"/><path d="m9 9 6 6M15 9l-6 6"/>\n  {%- elif name == \'ban\' -%}\n    <circle cx="12" cy="12" r="9"/><path d="m5.6 5.6 12.8 12.8"/>\n  {%- elif name == \'refresh\' -%}\n    <path d="M21 12a9 9 0 1 1-2.6-6.4"/><path d="M21 4v5h-5"/>\n  {%- elif name == \'eye\' -%}\n    <path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>\n  {%- elif name == \'eye-off\' -%}\n    <path d="M3 3l18 18"/><path d="M10.6 10.6a3 3 0 0 0 4.2 4.2"/><path d="M9.9 5.2A11 11 0 0 1 12 5c6.5 0 10 7 10 7a17 17 0 0 1-3.2 4.1M6.4 6.4A17.8 17.8 0 0 0 2 12s3.5 7 10 7a10.8 10.8 0 0 0 4.2-.8"/>\n  {%- elif name == \'help\' -%}\n    <circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4 2c-.9.7-1.5 1.2-1.5 2.5M12 17h.01"/>\n  {%- elif name == \'external\' -%}\n    <path d="M14 4h6v6M20 4l-9 9"/><path d="M19 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1h5"/>\n  {%- elif name == \'menu\' -%}\n    <path d="M4 7h16M4 12h16M4 17h16"/>\n  {%- elif name == \'spark\' -%}\n    <path d="M12 3v4M12 17v4M3 12h4M17 12h4M5.6 5.6l2.8 2.8M15.6 15.6l2.8 2.8M18.4 5.6l-2.8 2.8M8.4 15.6l-2.8 2.8"/>\n  {%- elif name == \'sun\' -%}\n    <circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>\n  {%- elif name == \'trash\' -%}\n    <path d="M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14"/><path d="M10 11v6M14 11v6"/>\n  {%- elif name == \'key\' -%}\n    <circle cx="8" cy="15" r="4"/><path d="m11 12 9-9M17 6l3 3M14 9l2 2"/>\n  {%- elif name == \'edit\' -%}\n    <path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z"/>\n  {%- endif -%}\n</svg>\n{%- endmacro %}\n\n{% macro logo(size=38, inverse=false) -%}\n<span class="brand{% if inverse %} brand--inverse{% endif %}">\n  <span class="brand-mark" style="--logo-size: {{ size }}px">\n    <img src="{{ url_for(\'static\', filename=\'img/idb-logo.png\') }}" width="{{ size }}" height="{{ size }}" alt="">\n  </span>\n  <span class="brand-text">\n    <span class="brand-name">IDB <em>Room</em></span>\n    <span class="brand-sub">Sistem Reservasi Ruangan</span>\n  </span>\n</span>\n{%- endmacro %}\n',
    '_ui.html': '{% from "_icons.html" import icon %}\n\n{% macro status_badge(label, tone, icon_name=None) -%}\n<span class="badge badge--{{ tone }}">\n  {% if icon_name %}{{ icon(icon_name, 14) }}{% else %}<span class="badge-dot" aria-hidden="true"></span>{% endif %}\n  {{ label }}\n</span>\n{%- endmacro %}\n\n{% macro status_for(state) -%}\n  {% set labels = {\n    \'pending\': \'Menunggu persetujuan\',\n    \'approved\': \'Disetujui\',\n    \'in_use\': \'Sedang digunakan\',\n    \'completed\': \'Selesai\',\n    \'rejected\': \'Ditolak\',\n    \'cancelled\': \'Dibatalkan\',\n    \'available\': \'Tersedia\',\n    \'inactive\': \'Tidak tersedia\'\n  } %}\n  {% set tones = {\n    \'pending\': \'warning\', \'approved\': \'success\', \'in_use\': \'info\',\n    \'completed\': \'neutral\', \'rejected\': \'danger\', \'cancelled\': \'neutral\',\n    \'available\': \'success\', \'inactive\': \'neutral\'\n  } %}\n  {% set icons = {\n    \'pending\': \'clock\', \'approved\': \'check-circle\', \'in_use\': \'door\',\n    \'completed\': \'check\', \'rejected\': \'x-circle\', \'cancelled\': \'ban\',\n    \'available\': \'check-circle\', \'inactive\': \'ban\'\n  } %}\n  {{ status_badge(labels.get(state, state), tones.get(state, \'neutral\'), icons.get(state, \'info\')) }}\n{%- endmacro %}\n\n{% macro empty_state(icon_name, title, text, action_url=None, action_label=None) -%}\n<div class="empty-state">\n  <span class="empty-icon" aria-hidden="true">{{ icon(icon_name, 26) }}</span>\n  <h3>{{ title }}</h3>\n  <p>{{ text }}</p>\n  {% if action_url and action_label %}\n    <a class="btn btn--secondary btn--sm" href="{{ action_url }}">{{ action_label }}</a>\n  {% endif %}\n</div>\n{%- endmacro %}\n\n{% macro room_card(room, state) -%}\n<article class="room-card room-card--{{ room[\'building\']|gedung }}">\n  <a class="room-card-link" href="{{ url_for(\'room_detail\', room_id=room[\'id\']) }}">\n    <div class="room-card-top">\n      <span class="room-code">{{ room[\'code\'] }}</span>\n      {{ status_badge(state[\'label\'], state[\'tone\'], \'door\' if state[\'key\'] == \'in_use\' else (\'check-circle\' if state[\'key\'] == \'available\' else \'ban\')) }}\n    </div>\n    <h3>{{ room[\'name\'] }}</h3>\n    <p class="room-meta">\n      {{ icon(\'map-pin\', 15) }} {{ room[\'building\'] }}{% if room[\'floor\'] %} · {{ room[\'floor\'] }}{% endif %}\n    </p>\n    <div class="room-card-foot">\n      <span class="room-kind">{{ room[\'kind\'] }}</span>\n      {% if state[\'next\'] %}\n        <span class="room-next">Dipesan {{ state[\'next\'][\'start_time\']|jam }}</span>\n      {% else %}\n        <span class="room-next">Lihat jadwal {{ icon(\'arrow-right\', 14) }}</span>\n      {% endif %}\n    </div>\n  </a>\n</article>\n{%- endmacro %}\n\n{% macro reservation_row(row, state, show_org=False, admin=False) -%}\n<article class="booking-row">\n  <div class="booking-date" aria-hidden="true">\n    <span class="booking-day">{{ row[\'date\'][8:10] }}</span>\n    <span class="booking-month">{{ row[\'date\']|bulan }}</span>\n  </div>\n  <div class="booking-main">\n    <div class="booking-title-line">\n      <h3><a href="{{ url_for(\'reservation_detail\', reservation_id=row[\'id\']) }}">{{ row[\'purpose\'] }}</a></h3>\n      {{ status_for(state) }}\n    </div>\n    <p class="booking-meta">\n      <span>{{ icon(\'calendar\', 14) }} {{ row[\'date\']|tgl_singkat }}</span>\n      <span>{{ icon(\'clock\', 14) }} {{ row[\'start_time\']|jam }}–{{ row[\'end_time\']|jam }} WITA</span>\n      {% if show_org %}<span>{{ icon(\'users\', 14) }} {{ row[\'organization_short\'] }}</span>{% endif %}\n    </p>\n    <p class="booking-room">{{ icon(\'door\', 14) }}\n      {% if row[\'room_id\'] %}{{ row[\'room_code\'] }} · {{ row[\'room_name\'] }}{% else %}{{ row[\'custom_room\'] or \'Ruangan lain\' }}{% endif %}\n      {% if admin %}<span class="booking-code">{{ row[\'code\'] }}</span>{% endif %}\n    </p>\n  </div>\n</article>\n{%- endmacro %}\n',
    'admin/dashboard.html': '{% extends "base.html" %}\n{% from "_icons.html" import icon %}\n{% from "_ui.html" import status_for, empty_state %}\n{% block title %}Admin{% endblock %}\n\n{% block content %}\n<section class="page-head">\n  <div class="page-head-copy">\n    <p class="eyebrow">{{ today|tgl }} · WITA</p>\n    <h1>Pusat kendali reservasi</h1>\n    <p class="page-sub">Tinjau pengajuan, jaga agar tidak ada slot yang disetujui dua kali, dan pantau pemakaian ruangan.</p>\n  </div>\n  <div class="page-actions">\n    <a class="btn btn--secondary" href="{{ url_for(\'admin_settings\') }}">{{ icon(\'settings\', 17) }} Pengaturan</a>\n    <a class="btn btn--primary" href="{{ url_for(\'admin_reservations\') }}">{{ icon(\'list\', 18) }} Semua reservasi</a>\n  </div>\n</section>\n\n<section class="stat-grid" aria-label="Ringkasan kampus">\n  <article class="stat-card">\n    <span class="stat-icon stat-icon--warning" aria-hidden="true">{{ icon(\'clock\', 20) }}</span>\n    <div><p class="stat-label">Menunggu tinjauan</p><p class="stat-value">{{ stats[\'pending\'] }}</p><p class="stat-hint">Perlu keputusan admin</p></div>\n  </article>\n  <article class="stat-card">\n    <span class="stat-icon stat-icon--success" aria-hidden="true">{{ icon(\'check-circle\', 20) }}</span>\n    <div><p class="stat-label">Disetujui hari ini</p><p class="stat-value">{{ stats[\'approved_today\'] }}</p><p class="stat-hint">Kegiatan terjadwal hari ini</p></div>\n  </article>\n  <article class="stat-card">\n    <span class="stat-icon stat-icon--brand" aria-hidden="true">{{ icon(\'calendar\', 20) }}</span>\n    <div><p class="stat-label">Tujuh hari ke depan</p><p class="stat-value">{{ stats[\'upcoming_week\'] }}</p><p class="stat-hint">Reservasi disetujui</p></div>\n  </article>\n  <article class="stat-card">\n    <span class="stat-icon stat-icon--neutral" aria-hidden="true">{{ icon(\'door\', 20) }}</span>\n    <div><p class="stat-label">Ruangan aktif</p><p class="stat-value">{{ stats[\'active_rooms\'] }}</p><p class="stat-hint"><a href="{{ url_for(\'admin_rooms\') }}">Kelola ruangan</a></p></div>\n  </article>\n</section>\n\n<section class="card" aria-labelledby="queue-title">\n  <div class="card-head">\n    <div>\n      <h2 id="queue-title">Antrean persetujuan</h2>\n      <p class="card-sub">Diurutkan dari tanggal kegiatan terdekat. Periksa konflik sebelum menyetujui.</p>\n    </div>\n    <a class="text-link" href="{{ url_for(\'admin_reservations\', status=\'pending\') }}">Lihat semua {{ icon(\'arrow-right\', 15) }}</a>\n  </div>\n\n  {% if pending %}\n    <div class="queue-list">\n      {% for item in pending %}\n        {% set row = item.row %}\n        <article class="queue-item">\n          <div class="queue-main">\n            <div class="queue-top">\n              <span class="queue-code">{{ row[\'code\'] }}</span>\n              <span class="badge badge--warning">{{ icon(\'clock\', 14) }} Menunggu</span>\n              {% if item.approved_conflicts %}\n                <span class="badge badge--danger">{{ icon(\'alert\', 14) }} Bentrok jadwal</span>\n              {% elif item.pending_conflicts %}\n                <span class="badge badge--warning">{{ icon(\'alert\', 14) }} Bersaing dengan pengajuan lain</span>\n              {% endif %}\n            </div>\n            <h3>{{ row[\'purpose\'] }}</h3>\n            <p class="queue-meta">\n              <span>{{ icon(\'user\', 14) }} {{ row[\'pic_name\'] }}</span>\n              <span>{{ icon(\'users\', 14) }} {{ row[\'organization_short\'] }}</span>\n              <span>{{ icon(\'door\', 14) }} {{ row[\'room_code\'] }} · {{ row[\'room_name\'] }}</span>\n              <span>{{ icon(\'calendar\', 14) }} {{ row[\'date\']|tgl_singkat }}</span>\n              <span>{{ icon(\'clock\', 14) }} {{ row[\'start_time\']|jam }}–{{ row[\'end_time\']|jam }} WITA</span>\n            </p>\n            {% if item.approved_conflicts %}\n              <div class="queue-conflict">\n                {{ icon(\'alert\', 16) }}\n                <p>Bertabrakan dengan reservasi disetujui:\n                  {% for conflict in item.approved_conflicts %}\n                    <a href="{{ url_for(\'reservation_detail\', reservation_id=conflict[\'id\']) }}">{{ conflict[\'code\'] }}</a>{% if not loop.last %}, {% endif %}\n                  {% endfor %}\n                </p>\n              </div>\n            {% endif %}\n            {% if item.pending_conflicts %}\n              <div class="queue-conflict queue-conflict--soft">\n                {{ icon(\'info\', 16) }}\n                <p>Pengajuan lain pada slot sama:\n                  {% for conflict in item.pending_conflicts %}\n                    <a href="{{ url_for(\'reservation_detail\', reservation_id=conflict[\'id\']) }}">{{ conflict[\'code\'] }}</a>{% if not loop.last %}, {% endif %}\n                  {% endfor %}. Selesaikan salah satu lebih dahulu.\n                </p>\n              </div>\n            {% endif %}\n          </div>\n          <div class="queue-actions">\n            <a class="btn btn--primary btn--sm" href="{{ url_for(\'reservation_detail\', reservation_id=row[\'id\']) }}">Tinjau</a>\n            <span class="queue-age">Diajukan {{ row[\'created_at\']|waktu }}</span>\n          </div>\n        </article>\n      {% endfor %}\n    </div>\n  {% else %}\n    {{ empty_state(\'check-circle\', \'Semua pengajuan sudah diproses\', \'Tidak ada antrean saat ini. Antrean baru akan muncul di sini.\', url_for(\'admin_reservations\'), \'Lihat riwayat reservasi\') }}\n  {% endif %}\n</section>\n\n<div class="dashboard-grid">\n  <section class="card" aria-labelledby="today-title">\n    <div class="card-head">\n      <div>\n        <h2 id="today-title">Jadwal hari ini</h2>\n        <p class="card-sub">Kegiatan disetujui dan yang masih menunggu.</p>\n      </div>\n      <a class="text-link" href="{{ url_for(\'calendar_view\') }}">Kalender {{ icon(\'arrow-right\', 15) }}</a>\n    </div>\n    {% if today_agenda %}\n      <div class="agenda-list">\n        {% for row in today_agenda %}\n          <div class="agenda-item">\n            <span class="agenda-time">{{ row[\'start_time\']|jam }}<small>{{ row[\'end_time\']|jam }}</small></span>\n            <span class="agenda-bar" aria-hidden="true"></span>\n            <span class="agenda-main">\n              <strong>{{ row[\'purpose\'] }}</strong>\n              <span>{{ row[\'organization_short\'] }} · {{ row[\'room_code\'] }} {{ row[\'room_name\'] }}</span>\n            </span>\n            {{ status_for(row|status_state) }}\n          </div>\n        {% endfor %}\n      </div>\n    {% else %}\n      {{ empty_state(\'sun\', \'Tidak ada kegiatan hari ini\', \'Kalender kampus kosong. Pengajuan baru akan tampil di sini.\') }}\n    {% endif %}\n  </section>\n\n  <section class="card" aria-labelledby="recent-title">\n    <div class="card-head">\n      <div>\n        <h2 id="recent-title">Aktivitas terbaru</h2>\n        <p class="card-sub">Keputusan dan pengajuan 14 hari terakhir.</p>\n      </div>\n    </div>\n    {% if recent %}\n      <ul class="activity-list">\n        {% for row in recent %}\n          <li>\n            <a href="{{ url_for(\'reservation_detail\', reservation_id=row[\'id\']) }}">\n              <span class="activity-main">\n                <strong>{{ row[\'organization_short\'] }} · {{ row[\'room_code\'] or row[\'custom_room\'] }}</strong>\n                <small>{{ row[\'date\']|tgl_singkat }} · {{ row[\'start_time\']|jam }}–{{ row[\'end_time\']|jam }}</small>\n                <small class="activity-code">{{ row[\'code\'] }}</small>\n              </span>\n              {{ status_for(row|status_state) }}\n            </a>\n          </li>\n        {% endfor %}\n      </ul>\n    {% else %}\n      <p class="muted">Belum ada aktivitas.</p>\n    {% endif %}\n  </section>\n</div>\n{% endblock %}\n',
    'admin/organizations.html': '{% extends "base.html" %}\n{% from "_icons.html" import icon %}\n{% from "_ui.html" import empty_state %}\n{% block title %}Organisasi{% endblock %}\n\n{% block content %}\n<section class="page-head">\n  <div class="page-head-copy">\n    <p class="eyebrow">Administrasi</p>\n    <h1>Organisasi &amp; akun</h1>\n    <p class="page-sub">Aktifkan atau nonaktifkan akses organisasi. Menonaktifkan organisasi juga menonaktifkan akunnya.</p>\n  </div>\n</section>\n\n<div class="notice">\n  {{ icon(\'info\', 18) }}\n  <p>Reset kata sandi membuat kata sandi sementara yang hanya ditampilkan sekali. Sampaikan langsung kepada pengurus organisasi terkait.</p>\n</div>\n\n<form class="filter-bar filter-bar--compact" method="get" action="{{ url_for(\'admin_organizations\') }}" role="search">\n  <div class="field field--inline">\n    <label for="q">Cari organisasi</label>\n    <div class="input-with-icon">\n      {{ icon(\'search\', 18) }}\n      <input id="q" name="q" type="search" value="{{ query_text }}" placeholder="Nama organisasi atau akun">\n    </div>\n  </div>\n  <div class="filter-actions">\n    <button class="btn btn--secondary" type="submit">{{ icon(\'search\', 17) }} Cari</button>\n    {% if query_text %}<a class="text-link" href="{{ url_for(\'admin_organizations\') }}">Bersihkan</a>{% endif %}\n  </div>\n</form>\n\n<p class="list-foot list-foot--left">{{ rows|length }} organisasi{% if query_text %} untuk “{{ query_text }}”{% endif %}.</p>\n\n{% if rows %}\n<div class="table-wrap">\n  <table class="data-table">\n    <caption class="sr-only">Daftar organisasi dan akun</caption>\n    <thead>\n      <tr>\n        <th scope="col">Organisasi</th>\n        <th scope="col">Akun</th>\n        <th scope="col">Reservasi</th>\n        <th scope="col">Status</th>\n        <th scope="col"><span class="sr-only">Aksi</span></th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for row in rows %}\n        <tr>\n          <td data-label="Organisasi">\n            <div class="org-cell">\n              <span class="avatar" aria-hidden="true">{{ row[\'name\']|inisial }}</span>\n              <strong>{{ row[\'name\'] }}</strong>\n            </div>\n          </td>\n          <td data-label="Akun"><span class="mono">{{ row[\'user_email\'] or row[\'username\'] }}</span><br><span class="muted small">{{ row[\'username\'] }}</span></td>\n          <td data-label="Reservasi">{{ row[\'total\'] }}</td>\n          <td data-label="Status">\n            <span class="badge badge--{{ \'success\' if row[\'user_active\'] else \'neutral\' }}">\n              {{ icon(\'check-circle\' if row[\'user_active\'] else \'ban\', 14) }} {{ \'Aktif\' if row[\'user_active\'] else \'Nonaktif\' }}\n            </span>\n          </td>\n          <td data-label="Aksi">\n            <div class="row-actions">\n              <form method="post" action="{{ url_for(\'admin_org_status\', org_id=row[\'id\']) }}"\n                    data-confirm="{{ \'Nonaktifkan akses \' ~ row[\'name\'] ~ \'? Akun tidak dapat masuk sampai diaktifkan kembali.\' if row[\'active\'] else \'Aktifkan kembali akses \' ~ row[\'name\'] ~ \'?\' }}"\n                    data-confirm-label="{{ \'Ya, nonaktifkan\' if row[\'active\'] else \'Ya, aktifkan\' }}"\n                    data-confirm-tone="{{ \'danger\' if row[\'active\'] else \'primary\' }}">\n                <input type="hidden" name="_csrf" value="{{ csrf_token() }}">\n                <button class="text-link" type="submit">{{ \'Nonaktifkan\' if row[\'active\'] else \'Aktifkan\' }}</button>\n              </form>\n              <form method="post" action="{{ url_for(\'admin_org_reset\', org_id=row[\'id\']) }}"\n                    data-confirm="Reset kata sandi {{ row[\'name\'] }}? Kata sandi lama langsung tidak berlaku."\n                    data-confirm-label="Ya, reset sandi">\n                <input type="hidden" name="_csrf" value="{{ csrf_token() }}">\n                <button class="text-link text-link--danger" type="submit">{{ icon(\'key\', 15) }} Reset sandi</button>\n              </form>\n            </div>\n          </td>\n        </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% elif query_text %}\n  {{ empty_state(\'search\', \'Tidak ada organisasi yang cocok\', \'Coba nama lain atau bersihkan pencarian.\', url_for(\'admin_organizations\'), \'Bersihkan pencarian\') }}\n{% else %}\n  {{ empty_state(\'users\', \'Belum ada organisasi\', \'Tambahkan organisasi dan akunnya untuk mulai menerima pengajuan.\') }}\n{% endif %}\n{% endblock %}\n',
    'admin/reservations.html': '{% extends "base.html" %}\n{% from "_icons.html" import icon %}\n{% from "_ui.html" import status_for, empty_state %}\n{% block title %}Semua reservasi{% endblock %}\n\n{% block content %}\n<section class="page-head">\n  <div class="page-head-copy">\n    <p class="eyebrow">Administrasi</p>\n    <h1>Semua reservasi</h1>\n    <p class="page-sub">Cari, filter, dan tinjau pengajuan dari seluruh organisasi.</p>\n  </div>\n  <div class="page-actions">\n    <a class="btn btn--secondary" href="{{ url_for(\'admin_dashboard\') }}">{{ icon(\'arrow-left\', 18) }} Pusat kendali</a>\n  </div>\n</section>\n\n<nav class="status-tabs" aria-label="Filter status reservasi">\n  {% set tabs = [\n    (\'semua\', \'Semua\'), (\'pending\', \'Menunggu\'), (\'approved\', \'Disetujui\'),\n    (\'completed\', \'Selesai\'), (\'rejected\', \'Ditolak\'), (\'cancelled\', \'Dibatalkan\')\n  ] %}\n  {% for key, label in tabs %}\n    <a href="{{ url_for(\'admin_reservations\', status=key, ruangan=room_id, dari=date_from, sampai=date_to, q=query_text) }}"\n       {% if status == key %}aria-current="page"{% endif %}>\n      {{ label }} <span class="tab-count">{{ counts[key] }}</span>\n    </a>\n  {% endfor %}\n</nav>\n\n<form class="filter-bar filter-bar--admin" method="get" action="{{ url_for(\'admin_reservations\') }}">\n  <input type="hidden" name="status" value="{{ status }}">\n  <div class="field field--inline">\n    <label for="q">Cari</label>\n    <input id="q" name="q" type="search" value="{{ query_text }}" placeholder="Kode, kegiatan, organisasi">\n  </div>\n  <div class="field field--inline">\n    <label for="ruangan">Ruangan</label>\n    <select id="ruangan" name="ruangan">\n      <option value="">Semua ruangan</option>\n      {% for room in rooms %}\n        <option value="{{ room[\'id\'] }}" {% if room_id == room[\'id\'] %}selected{% endif %}>{{ room[\'code\'] }} · {{ room[\'name\'] }}</option>\n      {% endfor %}\n    </select>\n  </div>\n  <div class="field field--inline">\n    <label for="dari">Dari tanggal</label>\n    <input id="dari" name="dari" type="date" value="{{ date_from }}">\n  </div>\n  <div class="field field--inline">\n    <label for="sampai">Sampai tanggal</label>\n    <input id="sampai" name="sampai" type="date" value="{{ date_to }}">\n  </div>\n  <div class="filter-actions">\n    <button class="btn btn--secondary" type="submit">{{ icon(\'filter\', 17) }} Terapkan</button>\n    <a class="text-link" href="{{ url_for(\'admin_reservations\') }}">Reset</a>\n  </div>\n</form>\n\n{% if items %}\n  <div class="table-wrap">\n    <table class="data-table">\n      <caption class="sr-only">Daftar reservasi seluruh organisasi</caption>\n      <thead>\n        <tr>\n          <th scope="col">Kode</th>\n          <th scope="col">Kegiatan / organisasi</th>\n          <th scope="col">Ruangan</th>\n          <th scope="col">Tanggal</th>\n          <th scope="col">Waktu</th>\n          <th scope="col">Status</th>\n          <th scope="col"><span class="sr-only">Aksi</span></th>\n        </tr>\n      </thead>\n      <tbody>\n        {% for item in items %}\n          {% set row = item.row %}\n          <tr>\n            <td data-label="Kode" class="nowrap"><span class="mono">{{ row[\'code\'] }}</span></td>\n            <td data-label="Kegiatan"><strong>{{ row[\'purpose\'] }}</strong><br><span class="muted">{{ row[\'organization_short\'] }}</span></td>\n            <td data-label="Ruangan">{% if row[\'room_id\'] %}{{ row[\'room_code\'] }} · {{ row[\'room_name\'] }}{% else %}{{ row[\'custom_room\'] }}{% endif %}</td>\n            <td data-label="Tanggal" class="nowrap">{{ row[\'date\']|tgl_singkat }}</td>\n            <td data-label="Waktu" class="nowrap">{{ row[\'start_time\']|jam }}–{{ row[\'end_time\']|jam }}</td>\n            <td data-label="Status">{{ status_for(item.state) }}</td>\n            <td data-label="Aksi"><a class="text-link" href="{{ url_for(\'reservation_detail\', reservation_id=row[\'id\']) }}">Tinjau {{ icon(\'arrow-right\', 14) }}</a></td>\n          </tr>\n        {% endfor %}\n      </tbody>\n    </table>\n  </div>\n  <p class="list-foot">Menampilkan {{ items|length }} reservasi.</p>\n{% else %}\n  {{ empty_state(\'search\', \'Tidak ada reservasi yang cocok\', \'Ubah filter status, ruangan, atau rentang tanggal.\', url_for(\'admin_reservations\'), \'Reset filter\') }}\n{% endif %}\n{% endblock %}\n',
    'admin/room_form.html': '{% extends "base.html" %}\n{% from "_icons.html" import icon %}\n{% block title %}{{ \'Ubah ruangan\' if room else \'Tambah ruangan\' }}{% endblock %}\n\n{% block content %}\n<nav class="breadcrumb" aria-label="Breadcrumb">\n  <a href="{{ url_for(\'admin_rooms\') }}">Ruangan</a>\n  <span aria-hidden="true">/</span>\n  <span aria-current="page">{{ \'Ubah\' if room else \'Tambah\' }}</span>\n</nav>\n\n<section class="page-head">\n  <div class="page-head-copy">\n    <p class="eyebrow">Administrasi</p>\n    <h1>{{ \'Ubah ruangan\' if room else \'Tambah ruangan\' }}</h1>\n    <p class="page-sub">Kode dan nama ruangan tampil pada kalender dan formulir reservasi.</p>\n  </div>\n</section>\n\n{% if errors %}\n  <div class="alert alert--error" role="alert">\n    {{ icon(\'alert\', 20) }}\n    <p>Periksa kembali data ruangan sebelum menyimpan.</p>\n  </div>\n{% endif %}\n\n<form method="post" class="card form-card" novalidate>\n  <input type="hidden" name="_csrf" value="{{ csrf_token() }}">\n  <div class="form-grid">\n    <div class="field" id="field-code">\n      <label for="code">Kode ruangan <span class="req" aria-hidden="true">*</span></label>\n      <input id="code" name="code" type="text" value="{{ values[\'code\'] }}" placeholder="contoh: A.1.4" required\n             aria-describedby="code-hint{% if errors.get(\'code\') %} code-error{% endif %}"\n             {% if errors.get(\'code\') %}aria-invalid="true"{% endif %}>\n      <p class="hint" id="code-hint">Kode unik, mengikuti penomoran kampus.</p>\n      {% if errors.get(\'code\') %}<p class="error-text" id="code-error">{{ errors[\'code\'] }}</p>{% endif %}\n    </div>\n    <div class="field" id="field-name">\n      <label for="name">Nama ruangan <span class="req" aria-hidden="true">*</span></label>\n      <input id="name" name="name" type="text" value="{{ values[\'name\'] }}" placeholder="contoh: Studio Pola" required\n             aria-describedby="{% if errors.get(\'name\') %}name-error{% endif %}"\n             {% if errors.get(\'name\') %}aria-invalid="true"{% endif %}>\n      {% if errors.get(\'name\') %}<p class="error-text" id="name-error">{{ errors[\'name\'] }}</p>{% endif %}\n    </div>\n    <div class="field" id="field-building">\n      <label for="building">Gedung <span class="req" aria-hidden="true">*</span></label>\n      <input id="building" name="building" type="text" value="{{ values[\'building\'] }}" placeholder="contoh: Gedung A" required\n             {% if errors.get(\'building\') %}aria-invalid="true" aria-describedby="building-error"{% endif %}>\n      {% if errors.get(\'building\') %}<p class="error-text" id="building-error">{{ errors[\'building\'] }}</p>{% endif %}\n    </div>\n    <div class="field">\n      <label for="floor">Lantai</label>\n      <input id="floor" name="floor" type="text" value="{{ values[\'floor\'] }}" placeholder="contoh: Lantai 2">\n    </div>\n    <div class="field" id="field-kind">\n      <label for="kind">Jenis ruangan <span class="req" aria-hidden="true">*</span></label>\n      <input id="kind" name="kind" type="text" value="{{ values[\'kind\'] }}" placeholder="contoh: Ruang kuliah" required\n             {% if errors.get(\'kind\') %}aria-invalid="true" aria-describedby="kind-error"{% endif %}>\n      {% if errors.get(\'kind\') %}<p class="error-text" id="kind-error">{{ errors[\'kind\'] }}</p>{% endif %}\n    </div>\n  </div>\n  <div class="field" id="field-description">\n    <label for="description">Deskripsi</label>\n    <textarea id="description" name="description" rows="3" maxlength="300"\n              placeholder="Keterangan singkat tentang ruangan.">{{ values[\'description\'] }}</textarea>\n    <p class="hint">Opsional, maksimal 300 karakter.</p>\n  </div>\n  <div class="form-actions">\n    <a class="btn btn--secondary" href="{{ url_for(\'admin_rooms\') }}">Batal</a>\n    <button class="btn btn--primary" type="submit">{{ icon(\'check\', 18) }} {{ \'Simpan perubahan\' if room else \'Tambah ruangan\' }}</button>\n  </div>\n</form>\n{% endblock %}\n',
    'admin/rooms.html': '{% extends "base.html" %}\n{% from "_icons.html" import icon %}\n{% from "_ui.html" import empty_state %}\n{% block title %}Kelola ruangan{% endblock %}\n\n{% block content %}\n<section class="page-head">\n  <div class="page-head-copy">\n    <p class="eyebrow">Administrasi</p>\n    <h1>Kelola ruangan</h1>\n    <p class="page-sub">Ruangan nonaktif tidak muncul di formulir pengajuan, tetapi riwayatnya tetap tersimpan.</p>\n  </div>\n  <div class="page-actions">\n    <a class="btn btn--primary" href="{{ url_for(\'admin_room_new\') }}">{{ icon(\'plus\', 18) }} Tambah ruangan</a>\n  </div>\n</section>\n\n<form class="filter-bar filter-bar--compact" method="get" action="{{ url_for(\'admin_rooms\') }}" role="search">\n  <div class="field field--inline">\n    <label for="q">Cari ruangan</label>\n    <div class="input-with-icon">\n      {{ icon(\'search\', 18) }}\n      <input id="q" name="q" type="search" value="{{ query_text }}" placeholder="Kode, nama, gedung, atau jenis">\n    </div>\n  </div>\n  <div class="filter-actions">\n    <button class="btn btn--secondary" type="submit">{{ icon(\'search\', 17) }} Cari</button>\n    {% if query_text %}<a class="text-link" href="{{ url_for(\'admin_rooms\') }}">Bersihkan</a>{% endif %}\n  </div>\n</form>\n\n<p class="list-foot list-foot--left">{{ rooms|length }} ruangan{% if query_text %} untuk “{{ query_text }}”{% endif %}.</p>\n\n{% if rooms %}\n  <div class="table-wrap">\n    <table class="data-table">\n      <caption class="sr-only">Daftar ruangan kampus</caption>\n      <thead>\n        <tr>\n          <th scope="col">Kode</th>\n          <th scope="col">Ruangan</th>\n          <th scope="col">Lokasi</th>\n          <th scope="col">Jenis</th>\n          <th scope="col">Reservasi</th>\n          <th scope="col">Status</th>\n          <th scope="col"><span class="sr-only">Aksi</span></th>\n        </tr>\n      </thead>\n      <tbody>\n        {% for room in rooms %}\n          <tr>\n            <td data-label="Kode"><span class="mono">{{ room[\'code\'] }}</span></td>\n            <td data-label="Ruangan"><strong>{{ room[\'name\'] }}</strong></td>\n            <td data-label="Lokasi">{{ room[\'building\'] }}{% if room[\'floor\'] %} · {{ room[\'floor\'] }}{% endif %}</td>\n            <td data-label="Jenis">{{ room[\'kind\'] }}</td>\n            <td data-label="Reservasi">{{ counts[room[\'id\']] }}</td>\n            <td data-label="Status">\n              <span class="badge badge--{{ \'success\' if room[\'active\'] else \'neutral\' }}">\n                {{ icon(\'check-circle\' if room[\'active\'] else \'ban\', 14) }} {{ \'Aktif\' if room[\'active\'] else \'Nonaktif\' }}\n              </span>\n            </td>\n            <td data-label="Aksi">\n              <div class="row-actions">\n                <a class="text-link" href="{{ url_for(\'admin_room_edit\', room_id=room[\'id\']) }}">{{ icon(\'edit\', 15) }} Ubah</a>\n                <form method="post" action="{{ url_for(\'admin_room_status\', room_id=room[\'id\']) }}"\n                      data-confirm="{{ \'Nonaktifkan \' ~ room[\'name\'] ~ \'? Ruangan tidak lagi muncul di formulir pengajuan.\' if room[\'active\'] else \'Aktifkan kembali \' ~ room[\'name\'] ~ \'?\' }}"\n                      data-confirm-label="{{ \'Ya, nonaktifkan\' if room[\'active\'] else \'Ya, aktifkan\' }}"\n                      data-confirm-tone="{{ \'danger\' if room[\'active\'] else \'primary\' }}">\n                  <input type="hidden" name="_csrf" value="{{ csrf_token() }}">\n                  <button class="text-link text-link--danger" type="submit">\n                    {{ \'Nonaktifkan\' if room[\'active\'] else \'Aktifkan\' }}\n                  </button>\n                </form>\n              </div>\n            </td>\n          </tr>\n        {% endfor %}\n      </tbody>\n    </table>\n  </div>\n{% elif query_text %}\n  {{ empty_state(\'search\', \'Tidak ada ruangan yang cocok\', \'Coba kata kunci lain atau bersihkan pencarian.\', url_for(\'admin_rooms\'), \'Bersihkan pencarian\') }}\n{% else %}\n  {{ empty_state(\'door\', \'Belum ada ruangan\', \'Tambahkan ruangan pertama agar organisasi dapat mengajukan reservasi.\', url_for(\'admin_room_new\'), \'Tambah ruangan\') }}\n{% endif %}\n{% endblock %}\n',
    'admin/settings.html': '{% extends "base.html" %}\n{% from "_icons.html" import icon %}\n{% block title %}Pengaturan{% endblock %}\n\n{% block content %}\n<section class="page-head">\n  <div class="page-head-copy">\n    <p class="eyebrow">Administrasi</p>\n    <h1>Pengaturan reservasi</h1>\n    <p class="page-sub">Aturan ini berlaku untuk semua pengajuan baru dan pemeriksaan bentrok berikutnya.</p>\n  </div>\n</section>\n\n<form method="post" class="settings-form" novalidate>\n  <input type="hidden" name="_csrf" value="{{ csrf_token() }}">\n\n  <section class="card" aria-labelledby="ops-title">\n    <div class="section-head">\n      <span class="section-number" aria-hidden="true">01</span>\n      <div>\n        <h2 id="ops-title">Jam operasional</h2>\n        <p class="card-sub">Rentang waktu yang boleh diajukan untuk seluruh ruangan.</p>\n      </div>\n    </div>\n    <div class="form-grid">\n      <div class="field">\n        <label for="open_time">Jam buka</label>\n        <input id="open_time" name="open_time" type="time" value="{{ settings[\'open_time\'] }}" required>\n      </div>\n      <div class="field">\n        <label for="close_time">Jam tutup</label>\n        <input id="close_time" name="close_time" type="time" value="{{ settings[\'close_time\'] }}" required>\n      </div>\n    </div>\n  </section>\n\n  <section class="card" aria-labelledby="conflict-title">\n    <div class="section-head">\n      <span class="section-number" aria-hidden="true">02</span>\n      <div>\n        <h2 id="conflict-title">Pencegahan bentrok</h2>\n        <p class="card-sub">Jeda persiapan ikut dihitung pada kedua sisi rentang waktu.</p>\n      </div>\n    </div>\n    <div class="form-grid">\n      <div class="field">\n        <label for="buffer_minutes">Jeda pergantian (menit)</label>\n        <input id="buffer_minutes" name="buffer_minutes" type="number" min="0" max="120" step="5" value="{{ settings[\'buffer_minutes\'] }}" required>\n        <p class="hint">Contoh: 15 menit berarti reservasi 09.00–11.00 menahan slot hingga 11.15.</p>\n      </div>\n      <div class="field">\n        <label for="max_advance_days">Batas pengajuan (hari)</label>\n        <input id="max_advance_days" name="max_advance_days" type="number" min="1" max="365" value="{{ settings[\'max_advance_days\'] }}" required>\n        <p class="hint">Berapa hari ke depan pengajuan masih diterima.</p>\n      </div>\n      <div class="field">\n        <label for="cancel_deadline_hours">Batas pembatalan (jam sebelum mulai)</label>\n        <input id="cancel_deadline_hours" name="cancel_deadline_hours" type="number" min="0" max="168" value="{{ settings[\'cancel_deadline_hours\'] }}" required>\n        <p class="hint">0 berarti pembatalan masih bisa dilakukan sebelum jam mulai.</p>\n      </div>\n    </div>\n  </section>\n\n  <section class="card" aria-labelledby="duration-title">\n    <div class="section-head">\n      <span class="section-number" aria-hidden="true">03</span>\n      <div>\n        <h2 id="duration-title">Durasi pemakaian</h2>\n        <p class="card-sub">Batas bawah dan atas untuk satu pengajuan.</p>\n      </div>\n    </div>\n    <div class="form-grid">\n      <div class="field">\n        <label for="min_duration_minutes">Durasi minimal (menit)</label>\n        <input id="min_duration_minutes" name="min_duration_minutes" type="number" min="15" max="240" step="15" value="{{ settings[\'min_duration_minutes\'] }}" required>\n      </div>\n      <div class="field">\n        <label for="max_duration_hours">Durasi maksimal (jam)</label>\n        <input id="max_duration_hours" name="max_duration_hours" type="number" min="1" max="12" value="{{ settings[\'max_duration_hours\'] }}" required>\n      </div>\n    </div>\n  </section>\n\n  <div class="form-actions">\n    <a class="btn btn--secondary" href="{{ url_for(\'admin_dashboard\') }}">Batal</a>\n    <button class="btn btn--primary" type="submit">{{ icon(\'check\', 18) }} Simpan pengaturan</button>\n  </div>\n</form>\n{% endblock %}\n',
    'base.html': '{% from "_icons.html" import icon, logo %}\n<!doctype html>\n<html lang="id">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">\n  <meta name="theme-color" content="#044c71">\n  <meta name="apple-mobile-web-app-capable" content="yes">\n  <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">\n  <meta name="apple-mobile-web-app-title" content="IDB Room">\n  <meta name="mobile-web-app-capable" content="yes">\n  <link rel="manifest" href="{{ url_for(\'static\', filename=\'manifest.webmanifest\') }}">\n  <link rel="apple-touch-icon" href="{{ url_for(\'static\', filename=\'img/apple-touch-icon.png\') }}">\n  <title>{% block title %}IDB Room{% endblock %} · Kampus IDB Bali</title>\n  <link rel="preconnect" href="https://fonts.googleapis.com">\n  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n  <link href="https://fonts.googleapis.com/css2?family=Source+Sans+3:wght@400;500;600;700&family=Source+Serif+4:opsz,wght@8..60,600;8..60,700&display=swap" rel="stylesheet">\n  <link rel="icon" href="{{ url_for(\'static\', filename=\'img/favicon.png\') }}" type="image/png">\n  <link rel="stylesheet" href="{{ url_for(\'static\', filename=\'css/app.css\') }}">\n  {% block head %}{% endblock %}\n</head>\n<body class="{% block body_class %}{% endblock %}">\n<a class="skip-link" href="#main">Lewati ke konten utama</a>\n\n{% if g.user %}\n<header class="app-header">\n  <div class="shell header-inner">\n    <a class="brand-link" href="{{ url_for(\'dashboard\') }}" aria-label="IDB Room, ke beranda">{{ logo(38, true) }}</a>\n\n    <nav class="primary-nav" aria-label="Navigasi utama">\n      {% if g.user[\'role\'] == \'admin\' %}\n        <a href="{{ url_for(\'admin_dashboard\') }}" {% if active_endpoint == \'admin_dashboard\' %}aria-current="page"{% endif %}>Beranda</a>\n        <a href="{{ url_for(\'admin_reservations\') }}" {% if active_endpoint in (\'admin_reservations\', \'reservation_detail\') %}aria-current="page"{% endif %}>Reservasi</a>\n        <a href="{{ url_for(\'admin_rooms\') }}" {% if active_endpoint in (\'admin_rooms\', \'admin_room_new\', \'admin_room_edit\') %}aria-current="page"{% endif %}>Ruangan</a>\n        <a href="{{ url_for(\'admin_organizations\') }}" {% if active_endpoint == \'admin_organizations\' %}aria-current="page"{% endif %}>Organisasi</a>\n        <a href="{{ url_for(\'admin_settings\') }}" {% if active_endpoint == \'admin_settings\' %}aria-current="page"{% endif %}>Pengaturan</a>\n      {% else %}\n        <a href="{{ url_for(\'dashboard\') }}" {% if active_endpoint == \'dashboard\' %}aria-current="page"{% endif %}>Beranda</a>\n        <a href="{{ url_for(\'rooms\') }}" {% if active_endpoint in (\'rooms\', \'room_detail\') %}aria-current="page"{% endif %}>Ruangan</a>\n        <a href="{{ url_for(\'calendar_view\') }}" {% if active_endpoint == \'calendar_view\' %}aria-current="page"{% endif %}>Kalender</a>\n        <a href="{{ url_for(\'reservations\') }}" {% if active_endpoint in (\'reservations\', \'reservation_detail\', \'reservation_new\') %}aria-current="page"{% endif %}>Reservasi</a>\n      {% endif %}\n    </nav>\n\n    <div class="header-actions">\n      <a class="icon-link" href="{{ url_for(\'notifications\') }}" aria-label="Notifikasi{% if unread_count %}, {{ unread_count }} belum dibaca{% endif %}">\n        {{ icon(\'bell\', 21) }}\n        {% if unread_count %}<span class="badge-count" aria-hidden="true">{{ unread_count if unread_count < 10 else \'9+\' }}</span>{% endif %}\n      </a>\n      <div class="user-chip">\n        <span class="avatar" aria-hidden="true">{{ g.user[\'name\']|inisial }}</span>\n        <span class="user-meta">\n          <strong>{{ g.user[\'name\'] }}</strong>\n          <small>{% if g.user[\'role\'] == \'admin\' %}Administrator{% else %}Organisasi mahasiswa{% endif %}</small>\n        </span>\n      </div>\n      <form method="post" action="{{ url_for(\'logout\') }}">\n        <input type="hidden" name="_csrf" value="{{ csrf_token() }}">\n        <button class="icon-link" type="submit" aria-label="Keluar dari akun">{{ icon(\'logout\', 20) }}</button>\n      </form>\n    </div>\n  </div>\n</header>\n\n<div class="page">\n  <main id="main" class="shell" tabindex="-1">\n    {% with messages = get_flashed_messages(with_categories=true) %}\n      {% if messages %}\n        <div class="flash-stack">\n          {% for category, message in messages %}\n            <div class="alert alert--{{ category }}" role="{{ \'alert\' if category == \'error\' else \'status\' }}">\n              {{ icon(\'alert\' if category == \'error\' else (\'check-circle\' if category == \'success\' else \'info\'), 20) }}\n              <p>{{ message }}</p>\n              <button class="alert-close" type="button" data-dismiss-alert aria-label="Tutup pesan">{{ icon(\'x\', 18) }}</button>\n            </div>\n          {% endfor %}\n        </div>\n      {% endif %}\n    {% endwith %}\n    {% block content %}{% endblock %}\n  </main>\n</div>\n\n{% if g.user[\'role\'] == \'org\' %}\n<a class="fab" href="{{ url_for(\'reservation_new\') }}">{{ icon(\'plus\', 20) }} <span>Ajukan</span></a>\n{% endif %}\n\n<dialog id="confirm-dialog" class="dialog" aria-labelledby="confirm-title">\n  <div class="dialog-head">\n    <h2 id="confirm-title">Konfirmasi tindakan</h2>\n    <button class="icon-link" type="button" data-dialog-close aria-label="Tutup dialog">{{ icon(\'x\', 20) }}</button>\n  </div>\n  <div class="dialog-body">\n    <p data-confirm-message></p>\n  </div>\n  <div class="dialog-foot">\n    <button class="btn btn--secondary" type="button" data-dialog-close>Batal</button>\n    <button class="btn btn--danger" type="button" data-confirm-accept>Ya, lanjutkan</button>\n  </div>\n</dialog>\n\n<nav class="bottom-nav" aria-label="Navigasi bawah">\n  {% if g.user[\'role\'] == \'admin\' %}\n    <a href="{{ url_for(\'admin_dashboard\') }}" {% if active_endpoint == \'admin_dashboard\' %}aria-current="page"{% endif %}>{{ icon(\'home\', 21) }}<span>Beranda</span></a>\n    <a href="{{ url_for(\'admin_reservations\') }}" {% if active_endpoint in (\'admin_reservations\', \'reservation_detail\') %}aria-current="page"{% endif %}>{{ icon(\'list\', 21) }}<span>Reservasi</span></a>\n    <a href="{{ url_for(\'admin_rooms\') }}" {% if active_endpoint in (\'admin_rooms\', \'admin_room_new\', \'admin_room_edit\') %}aria-current="page"{% endif %}>{{ icon(\'door\', 21) }}<span>Ruangan</span></a>\n    <a href="{{ url_for(\'admin_organizations\') }}" {% if active_endpoint == \'admin_organizations\' %}aria-current="page"{% endif %}>{{ icon(\'users\', 21) }}<span>Organisasi</span></a>\n    <a href="{{ url_for(\'admin_settings\') }}" {% if active_endpoint == \'admin_settings\' %}aria-current="page"{% endif %}>{{ icon(\'settings\', 21) }}<span>Atur</span></a>\n  {% else %}\n    <a href="{{ url_for(\'dashboard\') }}" {% if active_endpoint == \'dashboard\' %}aria-current="page"{% endif %}>{{ icon(\'home\', 21) }}<span>Beranda</span></a>\n    <a href="{{ url_for(\'rooms\') }}" {% if active_endpoint in (\'rooms\', \'room_detail\') %}aria-current="page"{% endif %}>{{ icon(\'door\', 21) }}<span>Ruangan</span></a>\n    <a href="{{ url_for(\'calendar_view\') }}" {% if active_endpoint == \'calendar_view\' %}aria-current="page"{% endif %}>{{ icon(\'calendar\', 21) }}<span>Kalender</span></a>\n    <a href="{{ url_for(\'reservations\') }}" {% if active_endpoint in (\'reservations\', \'reservation_detail\', \'reservation_new\') %}aria-current="page"{% endif %}>{{ icon(\'list\', 21) }}<span>Reservasi</span></a>\n  {% endif %}\n</nav>\n{% else %}\n<main id="main" tabindex="-1">\n  {% block public_content %}{% endblock %}\n</main>\n{% endif %}\n\n<script src="{{ url_for(\'static\', filename=\'js/app.js\') }}" defer></script>\n{% block scripts %}{% endblock %}\n</body>\n</html>\n',
    'calendar.html': '{% extends "base.html" %}\n{% from "_icons.html" import icon %}\n{% from "_ui.html" import status_for, empty_state %}\n{% block title %}Kalender{% endblock %}\n\n{% block content %}\n<section class="page-head">\n  <div class="page-head-copy">\n    <p class="eyebrow">Ketersediaan kampus</p>\n    <h1>Kalender reservasi</h1>\n    <p class="page-sub">Lihat sebaran kegiatan per hari, lalu buka tanggal untuk melihat detail ruangan.</p>\n  </div>\n  <div class="page-actions">\n    <a class="btn btn--primary" href="{{ url_for(\'reservation_new\') }}">{{ icon(\'plus\', 18) }} Ajukan reservasi</a>\n  </div>\n</section>\n\n<form class="filter-bar filter-bar--compact" method="get" action="{{ url_for(\'calendar_view\') }}">\n  <input type="hidden" name="bulan" value="{{ anchor.strftime(\'%Y-%m\') }}">\n  <input type="hidden" name="tanggal" value="{{ selected.isoformat() }}">\n  <div class="field field--inline">\n    <label for="ruangan">Filter ruangan</label>\n    <select id="ruangan" name="ruangan">\n      <option value="">Semua ruangan</option>\n      {% for room in rooms %}\n        <option value="{{ room[\'id\'] }}" {% if room_id == room[\'id\'] %}selected{% endif %}>{{ room[\'code\'] }} · {{ room[\'name\'] }}</option>\n      {% endfor %}\n    </select>\n  </div>\n  <div class="filter-actions">\n    <button class="btn btn--secondary" type="submit">{{ icon(\'filter\', 17) }} Terapkan</button>\n    {% if room_id %}<a class="text-link" href="{{ url_for(\'calendar_view\', bulan=anchor.strftime(\'%Y-%m\'), tanggal=selected.isoformat()) }}">Semua ruangan</a>{% endif %}\n  </div>\n</form>\n\n<div class="calendar-layout">\n  <section class="card card--calendar" aria-labelledby="month-title">\n    <div class="calendar-head">\n      <a class="icon-link" href="{{ url_for(\'calendar_view\', bulan=previous_month.strftime(\'%Y-%m\'), tanggal=previous_month.isoformat(), ruangan=room_id) }}" aria-label="Bulan sebelumnya">{{ icon(\'chevron-left\', 20) }}</a>\n      <div class="calendar-title">\n        <h2 id="month-title">{{ month_label }}</h2>\n        <a href="{{ url_for(\'calendar_view\', bulan=today.strftime(\'%Y-%m\'), tanggal=today.isoformat(), ruangan=room_id) }}">Kembali ke hari ini</a>\n      </div>\n      <a class="icon-link" href="{{ url_for(\'calendar_view\', bulan=next_month.strftime(\'%Y-%m\'), tanggal=next_month.isoformat(), ruangan=room_id) }}" aria-label="Bulan berikutnya">{{ icon(\'chevron-right\', 20) }}</a>\n    </div>\n\n    <table class="calendar-table">\n      <caption class="sr-only">Kalender ketersediaan {{ month_label }}</caption>\n      <thead>\n        <tr>\n          {% for day_name in weekdays %}<th scope="col"><span aria-hidden="true">{{ day_name }}</span><span class="sr-only">{{ day_name }}</span></th>{% endfor %}\n        </tr>\n      </thead>\n      <tbody>\n        {% for week in weeks %}\n          <tr>\n            {% for day in week %}\n              {% set info = summary.get(day.isoformat(), {}) %}\n              {% set total = info.get(\'total\', 0) %}\n              <td class="{% if day.month != anchor.month %}is-outside{% endif %} {% if day == today %}is-today{% endif %} {% if day == selected %}is-selected{% endif %}">\n                <a href="{{ url_for(\'calendar_view\', bulan=anchor.strftime(\'%Y-%m\'), tanggal=day.isoformat(), ruangan=room_id) }}"\n                   aria-label="{{ day|tgl }}{% if total %}, {{ total }} reservasi{% else %}, belum ada reservasi{% endif %}"\n                   {% if day == selected %}aria-current="date"{% endif %}>\n                  <span class="cal-day">{{ day.day }}</span>\n                  {% if total %}\n                    <span class="cal-count" aria-hidden="true">{{ total }}</span>\n                    <span class="cal-dots" aria-hidden="true">\n                      {% if info.get(\'approved\') %}<span class="dot dot--success"></span>{% endif %}\n                      {% if info.get(\'pending\') %}<span class="dot dot--warning"></span>{% endif %}\n                    </span>\n                  {% endif %}\n                </a>\n              </td>\n            {% endfor %}\n          </tr>\n        {% endfor %}\n      </tbody>\n    </table>\n    <p class="legend">\n      <span><span class="legend-dot legend-dot--success"></span> Disetujui</span>\n      <span><span class="legend-dot legend-dot--warning"></span> Menunggu</span>\n      <span><span class="legend-dot legend-dot--brand"></span> Tanggal dipilih</span>\n    </p>\n  </section>\n\n  <section class="card" aria-labelledby="day-title">\n    <div class="card-head">\n      <div>\n        <h2 id="day-title">{{ selected|tgl }}</h2>\n        <p class="card-sub">{{ agenda|length }} kegiatan{% if room_id %} pada ruangan terpilih{% endif %}.</p>\n      </div>\n      <a class="text-link" href="{{ url_for(\'reservation_new\', tanggal=selected.isoformat()) }}">Ajukan {{ icon(\'arrow-right\', 15) }}</a>\n    </div>\n    {% if agenda %}\n      <div class="agenda-list">\n        {% for row in agenda %}\n          <div class="agenda-item">\n            <span class="agenda-time">{{ row[\'start_time\']|jam }}<small>{{ row[\'end_time\']|jam }}</small></span>\n            <span class="agenda-bar" aria-hidden="true"></span>\n            <span class="agenda-main">\n              <strong>{{ row[\'purpose\'] }}</strong>\n              <span>{{ row[\'organization_short\'] }} · {{ row[\'room_code\'] }} {{ row[\'room_name\'] }}</span>\n            </span>\n            {{ status_for(row|status_state) }}\n          </div>\n        {% endfor %}\n      </div>\n    {% else %}\n      {{ empty_state(\'sun\', \'Belum ada kegiatan\', \'Tanggal ini masih kosong. Ajukan ruangan untuk kegiatan organisasi Anda.\', url_for(\'reservation_new\', tanggal=selected.isoformat()), \'Ajukan pada tanggal ini\') }}\n    {% endif %}\n  </section>\n</div>\n{% endblock %}\n',
    'dashboard.html': '{% extends "base.html" %}\n{% from "_icons.html" import icon %}\n{% from "_ui.html" import status_for, empty_state, room_card %}\n{% block title %}Beranda{% endblock %}\n\n{% block content %}\n<section class="page-head">\n  <div class="page-head-copy">\n    <p class="eyebrow">{{ today|tgl }} · WITA</p>\n    <h1>Selamat datang, {{ g.user[\'name\'] }}.</h1>\n    <p class="page-sub">Pantau jadwal organisasi Anda dan temukan ruangan yang bebas hari ini.</p>\n  </div>\n  <div class="page-actions">\n    <a class="btn btn--primary" href="{{ url_for(\'reservation_new\') }}">{{ icon(\'plus\', 18) }} Ajukan reservasi</a>\n  </div>\n</section>\n\n<section class="stat-grid" aria-label="Ringkasan reservasi">\n  <article class="stat-card">\n    <span class="stat-icon stat-icon--warning" aria-hidden="true">{{ icon(\'clock\', 20) }}</span>\n    <div>\n      <p class="stat-label">Menunggu persetujuan</p>\n      <p class="stat-value">{{ stats[\'pending\'] }}</p>\n      <p class="stat-hint">Pengajuan yang belum diputuskan admin</p>\n    </div>\n  </article>\n  <article class="stat-card">\n    <span class="stat-icon stat-icon--success" aria-hidden="true">{{ icon(\'check-circle\', 20) }}</span>\n    <div>\n      <p class="stat-label">Disetujui mendatang</p>\n      <p class="stat-value">{{ stats[\'approved\'] }}</p>\n      <p class="stat-hint">Termasuk kegiatan yang sedang berlangsung</p>\n    </div>\n  </article>\n  <article class="stat-card">\n    <span class="stat-icon stat-icon--brand" aria-hidden="true">{{ icon(\'calendar\', 20) }}</span>\n    <div>\n      <p class="stat-label">Reservasi bulan ini</p>\n      <p class="stat-value">{{ stats[\'month_total\'] }}</p>\n      <p class="stat-hint">Seluruh status, organisasi Anda</p>\n    </div>\n  </article>\n  <article class="stat-card">\n    <span class="stat-icon stat-icon--neutral" aria-hidden="true">{{ icon(\'door\', 20) }}</span>\n    <div>\n      <p class="stat-label">Ruangan aktif</p>\n      <p class="stat-value">{{ stats[\'active_rooms\'] }}</p>\n      <p class="stat-hint"><a href="{{ url_for(\'rooms\') }}">Lihat semua ruangan</a></p>\n    </div>\n  </article>\n</section>\n\n<div class="dashboard-grid">\n  <section class="card" aria-labelledby="upcoming-title">\n    <div class="card-head">\n      <div>\n        <h2 id="upcoming-title">Jadwal terdekat</h2>\n        <p class="card-sub">Pengajuan aktif organisasi Anda.</p>\n      </div>\n      <a class="text-link" href="{{ url_for(\'reservations\') }}">Semua reservasi {{ icon(\'arrow-right\', 15) }}</a>\n    </div>\n    {% if upcoming %}\n      <div class="booking-list">\n        {% for row in upcoming %}\n          <a class="upcoming-item" href="{{ url_for(\'reservation_detail\', reservation_id=row[\'id\']) }}">\n            <span class="upcoming-date">\n              <strong>{{ row[\'date\'][8:10] }}</strong>\n              <small>{{ row[\'date\']|bulan }}</small>\n            </span>\n            <span class="upcoming-main">\n              <strong>{{ row[\'purpose\'] }}</strong>\n              <span class="upcoming-meta">\n                {{ row[\'start_time\']|jam }}–{{ row[\'end_time\']|jam }} WITA ·\n                {% if row[\'room_id\'] %}{{ row[\'room_code\'] }} {{ row[\'room_name\'] }}{% else %}{{ row[\'custom_room\'] }}{% endif %}\n              </span>\n              <span class="upcoming-tag">{{ row[\'date\']|relatif }}</span>\n            </span>\n            <span class="upcoming-side">{{ status_for(row|status_state) }}</span>\n          </a>\n        {% endfor %}\n      </div>\n    {% else %}\n      {{ empty_state(\'calendar\', \'Belum ada jadwal mendatang\', \'Ajukan ruangan untuk kegiatan organisasi Anda. Jadwal yang disetujui akan muncul di sini.\', url_for(\'reservation_new\'), \'Ajukan reservasi\') }}\n    {% endif %}\n  </section>\n\n  <section class="card" aria-labelledby="available-title">\n    <div class="card-head">\n      <div>\n        <h2 id="available-title">Tersedia sekarang</h2>\n        <p class="card-sub">Ruangan yang bisa langsung diajukan.</p>\n      </div>\n      <a class="text-link" href="{{ url_for(\'rooms\') }}">Semua {{ icon(\'arrow-right\', 15) }}</a>\n    </div>\n    {% if available %}\n      <ul class="available-list">\n        {% for room, state in available %}\n          <li>\n            <a href="{{ url_for(\'reservation_new\', ruangan=room[\'id\']) }}">\n              <span class="available-code">{{ room[\'code\'] }}</span>\n              <span class="available-main">\n                <strong>{{ room[\'name\'] }}</strong>\n                <small>{{ room[\'building\'] }} · {{ room[\'kind\'] }}</small>\n              </span>\n              {{ status_for(\'available\') }}\n            </a>\n          </li>\n        {% endfor %}\n      </ul>\n    {% elif in_use %}\n      <ul class="available-list">\n        {% for room, state in in_use %}\n          <li>\n            <a href="{{ url_for(\'room_detail\', room_id=room[\'id\']) }}">\n              <span class="available-code">{{ room[\'code\'] }}</span>\n              <span class="available-main">\n                <strong>{{ room[\'name\'] }}</strong>\n                <small>{{ state[\'label\'] }}{% if state[\'booking\'] %} hingga {{ state[\'booking\'][\'end_time\']|jam }}{% endif %}</small>\n              </span>\n              {{ status_for(\'in_use\') }}\n            </a>\n          </li>\n        {% endfor %}\n      </ul>\n      <p class="card-note">{{ icon(\'info\', 15) }} Semua ruangan lain sedang dipakai. Lihat jadwal untuk mencari waktu berikutnya.</p>\n    {% else %}\n      {{ empty_state(\'door\', \'Belum ada ruangan aktif\', \'Hubungi admin untuk mengaktifkan ruangan kampus.\') }}\n    {% endif %}\n  </section>\n</div>\n\n<section class="card" aria-labelledby="agenda-title">\n  <div class="card-head">\n    <div>\n      <h2 id="agenda-title">Agenda kampus hari ini</h2>\n      <p class="card-sub">Kegiatan yang sudah disetujui dan pengajuan yang masih menunggu.</p>\n    </div>\n    <a class="text-link" href="{{ url_for(\'calendar_view\') }}">Buka kalender {{ icon(\'arrow-right\', 15) }}</a>\n  </div>\n  {% if today_agenda %}\n    <div class="agenda-list">\n      {% for row in today_agenda %}\n        <div class="agenda-item">\n          <span class="agenda-time">{{ row[\'start_time\']|jam }}<small>{{ row[\'end_time\']|jam }}</small></span>\n          <span class="agenda-bar" aria-hidden="true"></span>\n          <span class="agenda-main">\n            <strong>{{ row[\'purpose\'] }}</strong>\n            <span>{{ row[\'organization_short\'] }} · {{ row[\'room_code\'] }} {{ row[\'room_name\'] }}</span>\n          </span>\n          {{ status_for(row|status_state) }}\n        </div>\n      {% endfor %}\n    </div>\n  {% else %}\n    {{ empty_state(\'sun\', \'Hari ini masih lengang\', \'Belum ada kegiatan yang tercatat. Jadilah yang pertama mengajukan ruangan.\') }}\n  {% endif %}\n</section>\n{% endblock %}\n',
    'error.html': '{% extends "base.html" %}\n{% block title %}{{ title }}{% endblock %}\n{% block content %}{% include "_error_body.html" %}{% endblock %}\n{% block public_content %}{% include "_error_body.html" %}{% endblock %}\n',
    'login.html': '{% extends "base.html" %}\n{% from "_icons.html" import icon, logo %}\n{% block title %}Masuk{% endblock %}\n{% block body_class %}login-page{% endblock %}\n\n{% block public_content %}\n<div class="login-shell">\n  <section class="login-hero" aria-labelledby="hero-title">\n    <div class="login-hero-art" aria-hidden="true"></div>\n    <div class="login-hero-content">\n      <p class="eyebrow eyebrow--light">Kampus IDB Bali · Bali, Indonesia</p>\n      <div class="hero-copy">\n        <h1 id="hero-title">Ruang untuk<br><em>setiap gagasan.</em></h1>\n        <p class="hero-lede">Satu papan jadwal untuk seluruh civitas akademika. Temukan ruang, ajukan waktu, dan hindari jadwal bertabrakan.</p>\n        <ul class="hero-points">\n          <li>{{ icon(\'calendar\', 18) }} <span>Ketersediaan ruangan yang selalu diperbarui</span></li>\n          <li>{{ icon(\'shield\', 18) }} <span>Pemeriksaan bentrok otomatis, dua arah</span></li>\n          <li>{{ icon(\'file\', 18) }} <span>Riwayat pengajuan yang rapi dan tertelusur</span></li>\n        </ul>\n      </div>\n      <div class="hero-foot">\n        <span>Institut Desain &amp; Bisnis Bali</span>\n        <span class="hero-line" aria-hidden="true"></span>\n        <span>WITA · UTC+8</span>\n      </div>\n    </div>\n  </section>\n\n  <section class="login-panel" aria-labelledby="login-title">\n    <div class="login-pattern" aria-hidden="true"></div>\n    <div class="login-panel-inner">\n      <div class="login-brand">{{ logo(46) }}</div>\n\n      <div class="login-heading">\n        <h2 id="login-title">Masuk ke akun</h2>\n      </div>\n\n      {% if error %}\n        <div class="alert alert--error" role="alert" id="login-error" tabindex="-1">\n          {{ icon(\'alert\', 20) }}\n          <p>{{ error }}</p>\n        </div>\n      {% endif %}\n\n      <form method="post" action="{{ url_for(\'login\') }}" class="login-form" novalidate>\n        <input type="hidden" name="_csrf" value="{{ csrf_token() }}">\n        <input type="hidden" name="next" value="{{ next_target }}">\n\n        <div class="field">\n          <label for="username">Email</label>\n          <div class="input-with-icon">\n            {{ icon(\'user\', 19) }}\n            <input id="username" name="username" type="email" inputmode="email" autocomplete="username"\n                   placeholder="nama@idbbali.ac.id" value="{{ username }}" required\n                   {% if error %}aria-describedby="login-error"{% endif %}>\n          </div>\n        </div>\n\n        <div class="field">\n          <label for="password">Kata sandi</label>\n          <div class="input-with-icon input-with-action">\n            {{ icon(\'lock\', 19) }}\n            <input id="password" name="password" type="password" autocomplete="current-password"\n                   placeholder="Masukkan kata sandi" required\n                   {% if error %}aria-describedby="login-error"{% endif %}>\n            <button class="input-action" type="button" data-toggle-password aria-label="Tampilkan kata sandi" aria-pressed="false">\n              <span data-eye-show>{{ icon(\'eye\', 19) }}</span>\n              <span data-eye-hide hidden>{{ icon(\'eye-off\', 19) }}</span>\n            </button>\n          </div>\n        </div>\n\n        <div class="login-actions">\n          <button class="btn btn--help" type="button" data-dialog-open="help-dialog">\n            {{ icon(\'help\', 19) }} Butuh bantuan?\n          </button>\n          <button class="btn btn--primary" type="submit">\n            Masuk {{ icon(\'arrow-right\', 19) }}\n          </button>\n        </div>\n      </form>\n\n      <details class="demo-accounts">\n        <summary>Akun demo untuk uji coba</summary>\n        <div class="demo-grid">\n          <div><span class="demo-role">Organisasi</span><code>bem@idbbali.ac.id</code><span class="demo-sep">/</span><code>idb2026</code></div>\n          <div><span class="demo-role">Admin</span><code>admin@idbbali.ac.id</code><span class="demo-sep">/</span><code>admin2026</code></div>\n        </div>\n      </details>\n\n      <footer class="login-footer">\n        <p>© 2026 Kampus IDB Bali · Bagian Sistem Informasi</p>\n        <p class="login-footer-note">Akses hanya untuk civitas akademika IDB Bali dan admin yang berwenang.</p>\n      </footer>\n    </div>\n  </section>\n</div>\n\n<dialog id="help-dialog" class="dialog" aria-labelledby="help-title">\n  <div class="dialog-head">\n    <h2 id="help-title">Tidak bisa masuk?</h2>\n    <button class="icon-link" type="button" data-dialog-close aria-label="Tutup bantuan">{{ icon(\'x\', 20) }}</button>\n  </div>\n  <div class="dialog-body">\n    <p>Akun dibuat dan dikelola oleh admin reservasi kampus. Jika kata sandi hilang atau akun belum aktif, hubungi Bagian Sistem Informasi IDB Bali dengan menyertakan nama organisasi Anda.</p>\n    <ul class="dialog-list">\n      <li>Gunakan email kampus yang terdaftar tanpa spasi.</li>\n      <li>Kata sandi bersifat peka huruf besar dan kecil.</li>\n      <li>Untuk uji coba, gunakan akun demo di atas.</li>\n    </ul>\n  </div>\n  <div class="dialog-foot">\n    <button class="btn btn--primary" type="button" data-dialog-close>Mengerti</button>\n  </div>\n</dialog>\n{% endblock %}\n',
    'notifications.html': '{% extends "base.html" %}\n{% from "_icons.html" import icon %}\n{% from "_ui.html" import empty_state %}\n{% block title %}Notifikasi{% endblock %}\n\n{% block content %}\n<section class="page-head">\n  <div class="page-head-copy">\n    <p class="eyebrow">Kotak masuk</p>\n    <h1>Notifikasi</h1>\n    <p class="page-sub">Perubahan status reservasi Anda akan muncul di sini.</p>\n  </div>\n</section>\n\n{% if rows %}\n  <section class="card card--list" aria-label="Daftar notifikasi">\n    {% for row in rows %}\n      <article class="notification-row">\n        <span class="notification-icon" aria-hidden="true">{{ icon(\'bell\', 19) }}</span>\n        <div>\n          <strong>{{ row[\'title\'] }}</strong>\n          <p>{{ row[\'message\'] }}</p>\n          <time class="muted">{{ row[\'created_at\']|waktu }}</time>\n        </div>\n        {% if row[\'reservation_id\'] %}\n          <a class="text-link" href="{{ url_for(\'reservation_detail\', reservation_id=row[\'reservation_id\']) }}" aria-label="Buka reservasi {{ row[\'reservation_code\'] }}">Buka {{ icon(\'arrow-right\', 14) }}</a>\n        {% endif %}\n      </article>\n    {% endfor %}\n  </section>\n{% else %}\n  {{ empty_state(\'bell\', \'Belum ada notifikasi\', \'Saat admin menyetujui atau menolak pengajuan, kabarnya akan tampil di sini.\') }}\n{% endif %}\n{% endblock %}\n',
    'reservation_detail.html': '{% extends "base.html" %}\n{% from "_icons.html" import icon %}\n{% from "_ui.html" import status_for %}\n{% block title %}{{ row[\'code\'] }}{% endblock %}\n\n{% set is_admin = g.user[\'role\'] == \'admin\' %}\n{% set borrower_kind = row[\'borrower_type\'] or \'mahasiswa\' %}\n{% set borrower_type_label = \'Dosen\' if borrower_kind == \'dosen\' else (\'Organisasi mahasiswa\' if borrower_kind in (\'organisasi\', \'bem\') else \'Mahasiswa\') %}\n{% set borrower_name_label = \'Nama dosen\' if borrower_kind == \'dosen\' else \'Nama mahasiswa\' %}\n{% set borrower_id_label = \'NIDN/NIP\' if borrower_kind == \'dosen\' else \'NIM\' %}\n\n{% block content %}\n<nav class="breadcrumb" aria-label="Breadcrumb">\n  <a href="{{ url_for(\'admin_reservations\') if is_admin else url_for(\'reservations\') }}">Reservasi</a>\n  <span aria-hidden="true">/</span>\n  <span aria-current="page">{{ row[\'code\'] }}</span>\n</nav>\n\n<section class="page-head page-head--detail">\n  <div class="page-head-copy">\n    <p class="eyebrow">Kode reservasi · {{ row[\'code\'] }}</p>\n    <h1>{{ row[\'purpose\'] }}</h1>\n    <div class="head-badges">\n      {{ status_for(state) }}\n      <span class="pill pill--quiet">{{ icon(\'calendar\', 15) }} {{ row[\'date\']|tgl }}</span>\n      <span class="pill pill--quiet">{{ icon(\'clock\', 15) }} {{ row[\'start_time\']|jam }}–{{ row[\'end_time\']|jam }} WITA</span>\n    </div>\n  </div>\n  <div class="page-actions">\n    {% if is_admin and row[\'status\'] == \'pending\' %}\n      {% if conflicts or pending_conflicts %}\n        <button class="btn btn--secondary" type="button" disabled aria-describedby="conflict-title">{{ icon(\'check\', 18) }} Setujui</button>\n        <button class="btn btn--danger" type="button" data-dialog-open="reject-dialog">{{ icon(\'x\', 18) }} Tolak</button>\n      {% else %}\n        <button class="btn btn--primary" type="button" data-dialog-open="approve-dialog">{{ icon(\'check\', 18) }} Setujui</button>\n        <button class="btn btn--danger-ghost" type="button" data-dialog-open="reject-dialog">{{ icon(\'x\', 18) }} Tolak</button>\n      {% endif %}\n    {% endif %}\n    {% if can_cancel %}\n      <button class="btn btn--danger-ghost" type="button" data-dialog-open="cancel-dialog">{{ icon(\'ban\', 17) }} Batalkan</button>\n    {% endif %}\n  </div>\n</section>\n\n{% if row[\'status\'] == \'rejected\' %}\n  <div class="alert alert--error" role="status">\n    {{ icon(\'x-circle\', 20) }}\n    <p><strong>Permohonan ditolak.</strong> {{ row[\'note\'] or \'Admin tidak menyertakan catatan.\' }}</p>\n  </div>\n{% elif row[\'status\'] == \'cancelled\' %}\n  <div class="alert alert--info" role="status">\n    {{ icon(\'ban\', 20) }}\n    <p><strong>Reservasi dibatalkan.</strong> {{ row[\'note\'] or \'Slot sudah dilepas dari kalender.\' }}</p>\n  </div>\n{% elif state == \'in_use\' %}\n  <div class="alert alert--info" role="status">\n    {{ icon(\'door\', 20) }}\n    <p><strong>Sedang digunakan.</strong> Kegiatan berlangsung hingga {{ row[\'end_time\']|jam }} WITA.</p>\n  </div>\n{% endif %}\n\n{% if conflicts or pending_conflicts %}\n  <section class="conflict-panel" aria-labelledby="conflict-title">\n    <div class="conflict-head">\n      {{ icon(\'alert\', 20) }}\n      <h2 id="conflict-title">Periksa sebelum menyetujui</h2>\n    </div>\n    <p>Pengajuan ini bertabrakan dengan reservasi lain pada ruangan dan waktu yang sama.</p>\n    <ul>\n      {% for item in conflicts %}\n        <li>\n          <strong>{{ item[\'start_time\']|jam }}–{{ item[\'end_time\']|jam }} WITA</strong>\n          <a href="{{ url_for(\'reservation_detail\', reservation_id=item[\'id\']) }}">{{ item[\'code\'] }}</a>\n          <span>{{ item[\'organization_short\'] }}</span>\n          <span class="badge badge--success">Disetujui</span>\n        </li>\n      {% endfor %}\n      {% for item in pending_conflicts %}\n        <li>\n          <strong>{{ item[\'start_time\']|jam }}–{{ item[\'end_time\']|jam }} WITA</strong>\n          <a href="{{ url_for(\'reservation_detail\', reservation_id=item[\'id\']) }}">{{ item[\'code\'] }}</a>\n          <span>{{ item[\'organization_short\'] }}</span>\n          <span class="badge badge--warning">Menunggu</span>\n        </li>\n      {% endfor %}\n    </ul>\n    {% if conflicts %}\n      <p>Slot ini sudah dipakai reservasi yang disetujui. Pengajuan tidak dapat disetujui; tolak permohonan atau minta pemohon memilih waktu lain.</p>\n    {% else %}\n      <p>Selesaikan pengajuan lain terlebih dahulu (tolak atau setujui) agar tidak ada dua persetujuan pada slot yang sama.</p>\n    {% endif %}\n  </section>\n{% endif %}\n\n<div class="detail-grid">\n  <section class="card" aria-labelledby="info-title">\n    <h2 id="info-title">Detail permohonan</h2>\n    <dl class="detail-list">\n      <div><dt>Jenis peminjam</dt><dd>{{ borrower_type_label }}</dd></div>\n      <div><dt>{{ borrower_name_label }}</dt><dd>{{ row[\'pic_name\'] }}</dd></div>\n      <div><dt>{{ borrower_id_label }}</dt><dd class="mono">{{ row[\'identity_number\'] or \'—\' }}</dd></div>\n      <div><dt>Kontak</dt><dd>{{ row[\'pic_phone\'] }}</dd></div>\n      <div><dt>Ruangan</dt><dd>\n        {% if row[\'room_id\'] %}<a href="{{ url_for(\'room_detail\', room_id=row[\'room_id\'], tanggal=row[\'date\']) }}">{{ row[\'room_code\'] }} · {{ row[\'room_name\'] }}</a>{% else %}{{ row[\'custom_room\'] }}{% endif %}\n        {% if row[\'room_building\'] %}<br><span class="muted">{{ row[\'room_building\'] }}</span>{% endif %}\n      </dd></div>\n      <div><dt>Tanggal</dt><dd>{{ row[\'date\']|tgl }}</dd></div>\n      <div><dt>Waktu</dt><dd>{{ row[\'start_time\']|jam }}–{{ row[\'end_time\']|jam }} WITA</dd></div>\n      <div><dt>Diajukan</dt><dd>{{ row[\'created_at\']|waktu }}</dd></div>\n      <div><dt>Diproses</dt><dd>{{ row[\'decided_at\']|waktu if row[\'decided_at\'] else \'Belum diproses\' }}</dd></div>\n      <div><dt>Admin pemroses</dt><dd>{{ row[\'admin_name\'] or \'—\' }}</dd></div>\n      <div class="detail-wide"><dt>Tujuan kegiatan</dt><dd>{{ row[\'purpose\'] }}</dd></div>\n      {% if row[\'note\'] %}\n        <div class="detail-wide"><dt>Catatan</dt><dd>{{ row[\'note\'] }}</dd></div>\n      {% endif %}\n    </dl>\n  </section>\n\n  <aside class="detail-side">\n    <section class="card" aria-labelledby="timeline-title">\n      <h2 id="timeline-title">Riwayat status</h2>\n      {% if events %}\n        <ol class="timeline">\n          {% for event in events %}\n            {% set tone = \'success\' if event[\'action\'] == \'disetujui\' else (\'danger\' if event[\'action\'] == \'ditolak\' else (\'neutral\' if event[\'action\'] == \'dibatalkan\' else \'brand\')) %}\n            <li class="timeline-item timeline-item--{{ tone }}">\n              <span class="timeline-dot" aria-hidden="true"></span>\n              <div>\n                <strong>{{ event[\'action\']|capitalize }}</strong>\n                <p class="muted">{{ event[\'actor_name\'] or \'Sistem\' }}{% if event[\'actor_org\'] and event[\'actor_org\'] != event[\'actor_name\'] %} · {{ event[\'actor_org\'] }}{% endif %}</p>\n                <time>{{ event[\'created_at\']|waktu }}</time>\n                {% if event[\'note\'] %}<p class="timeline-note">{{ event[\'note\'] }}</p>{% endif %}\n              </div>\n            </li>\n          {% endfor %}\n        </ol>\n      {% else %}\n        <p class="muted">Belum ada riwayat.</p>\n      {% endif %}\n    </section>\n\n    <section class="card" aria-labelledby="help-title">\n      <h2 id="help-title">Butuh perubahan?</h2>\n      <p class="muted">Perubahan waktu atau ruangan dilakukan dengan membatalkan permohonan lalu mengajukan ulang. Hubungi admin bila kegiatan mendesak.</p>\n    </section>\n  </aside>\n</div>\n\n{% if can_cancel %}\n<dialog id="cancel-dialog" class="dialog" aria-labelledby="cancel-title">\n  <form method="post" action="{{ url_for(\'reservation_cancel\', reservation_id=row[\'id\']) }}">\n    <input type="hidden" name="_csrf" value="{{ csrf_token() }}">\n    <div class="dialog-head">\n      <h2 id="cancel-title">Batalkan {{ row[\'code\'] }}?</h2>\n      <button class="icon-link" type="button" data-dialog-close aria-label="Tutup dialog">{{ icon(\'x\', 20) }}</button>\n    </div>\n    <div class="dialog-body">\n      <p>Slot {{ row[\'room_code\'] or row[\'custom_room\'] }} pada {{ row[\'date\']|tgl }}, {{ row[\'start_time\']|jam }}–{{ row[\'end_time\']|jam }} WITA akan dilepas dari kalender. Tindakan ini tidak dapat dibatalkan.</p>\n      <div class="field">\n        <label for="cancel-note">Alasan pembatalan <span class="muted">(opsional)</span></label>\n        <textarea id="cancel-note" name="note" rows="3" placeholder="contoh: Kegiatan dijadwalkan ulang."></textarea>\n      </div>\n    </div>\n    <div class="dialog-foot">\n      <button class="btn btn--secondary" type="button" data-dialog-close>Pertahankan</button>\n      <button class="btn btn--danger" type="submit">Ya, batalkan reservasi</button>\n    </div>\n  </form>\n</dialog>\n{% endif %}\n\n{% if is_admin and row[\'status\'] == \'pending\' %}\n<dialog id="approve-dialog" class="dialog" aria-labelledby="approve-title">\n  <form method="post" action="{{ url_for(\'admin_decision\', reservation_id=row[\'id\']) }}">\n    <input type="hidden" name="_csrf" value="{{ csrf_token() }}">\n    <input type="hidden" name="action" value="approve">\n    <div class="dialog-head">\n      <h2 id="approve-title">Setujui {{ row[\'code\'] }}?</h2>\n      <button class="icon-link" type="button" data-dialog-close aria-label="Tutup dialog">{{ icon(\'x\', 20) }}</button>\n    </div>\n    <div class="dialog-body">\n      <p>Sistem akan memeriksa ulang bentrok. Jika slot masih aman, reservasi disetujui dan pemohon menerima notifikasi.</p>\n      <div class="field">\n        <label for="approve-note">Catatan untuk pemohon <span class="muted">(opsional)</span></label>\n        <textarea id="approve-note" name="note" rows="3" placeholder="contoh: Kunci diambil di resepsionis."></textarea>\n      </div>\n    </div>\n    <div class="dialog-foot">\n      <button class="btn btn--secondary" type="button" data-dialog-close>Batal</button>\n      <button class="btn btn--primary" type="submit">Setujui reservasi</button>\n    </div>\n  </form>\n</dialog>\n\n<dialog id="reject-dialog" class="dialog" aria-labelledby="reject-title">\n  <form method="post" action="{{ url_for(\'admin_decision\', reservation_id=row[\'id\']) }}">\n    <input type="hidden" name="_csrf" value="{{ csrf_token() }}">\n    <input type="hidden" name="action" value="reject">\n    <div class="dialog-head">\n      <h2 id="reject-title">Tolak {{ row[\'code\'] }}?</h2>\n      <button class="icon-link" type="button" data-dialog-close aria-label="Tutup dialog">{{ icon(\'x\', 20) }}</button>\n    </div>\n    <div class="dialog-body">\n      <p>Pemohon akan melihat alasan penolakan. Tuliskan alasan yang jelas agar organisasi dapat mengajukan waktu lain.</p>\n      <div class="field">\n        <label for="reject-note">Alasan penolakan <span class="req" aria-hidden="true">*</span></label>\n        <textarea id="reject-note" name="note" rows="4" required placeholder="contoh: Ruangan dipakai untuk ujian pada jam tersebut."></textarea>\n      </div>\n    </div>\n    <div class="dialog-foot">\n      <button class="btn btn--secondary" type="button" data-dialog-close>Batal</button>\n      <button class="btn btn--danger" type="submit">Tolak permohonan</button>\n    </div>\n  </form>\n</dialog>\n{% endif %}\n{% endblock %}\n',
    'reservation_new.html': '{% extends "base.html" %}\n{% from "_icons.html" import icon %}\n{% block title %}Ajukan reservasi{% endblock %}\n\n{% block content %}\n<nav class="breadcrumb" aria-label="Breadcrumb">\n  <a href="{{ url_for(\'reservations\') }}">Reservasi</a>\n  <span aria-hidden="true">/</span>\n  <span aria-current="page">Ajukan baru</span>\n</nav>\n\n<section class="page-head">\n  <div class="page-head-copy">\n    <p class="eyebrow">Formulir permohonan</p>\n    <h1>Ajukan reservasi ruangan</h1>\n    <p class="page-sub">Isi waktu dan tujuan kegiatan. Sistem akan memeriksa bentrok sebelum permohonan dikirim.</p>\n  </div>\n</section>\n\n{% if errors %}\n  <div class="alert alert--error" role="alert">\n    {{ icon(\'alert\', 20) }}\n    <div>\n      <p><strong>Permohonan belum bisa dikirim.</strong> Periksa {{ errors|length }} hal berikut:</p>\n      <ul class="alert-list">\n        {% for key, message in errors.items() %}\n          <li><a href="#field-{{ \'start_time\' if key == \'slot\' else key }}">{{ message }}</a></li>\n        {% endfor %}\n      </ul>\n    </div>\n  </div>\n{% endif %}\n\n{% if conflicts %}\n  <section class="conflict-panel" aria-labelledby="conflict-title">\n    <div class="conflict-head">\n      {{ icon(\'alert\', 20) }}\n      <h2 id="conflict-title">Jadwal bertabrakan</h2>\n    </div>\n    <ul>\n      {% for item in conflicts %}\n        <li>\n          <strong>{{ item[\'start_time\']|jam }}–{{ item[\'end_time\']|jam }} WITA</strong>\n          <span>{{ item[\'organization_short\'] }} · {{ item[\'code\'] }}</span>\n          <span class="badge badge--{{ \'warning\' if item[\'status\'] == \'pending\' else \'success\' }}">{{ \'Menunggu persetujuan\' if item[\'status\'] == \'pending\' else \'Disetujui\' }}</span>\n        </li>\n      {% endfor %}\n    </ul>\n    <p>Pilih waktu lain, atau periksa lagi bila jeda pergantian baru diubah admin.</p>\n  </section>\n{% endif %}\n\n<form method="post" class="reservation-form" novalidate data-reservation-form data-availability-url="{{ url_for(\'availability_api\') }}">\n  <input type="hidden" name="_csrf" value="{{ csrf_token() }}">\n\n  <div class="form-layout">\n    <div class="form-main">\n      <section class="card" aria-labelledby="who-title">\n        <div class="section-head">\n          <span class="section-number" aria-hidden="true">01</span>\n          <div>\n            <h2 id="who-title">Pemohon</h2>\n            <p class="card-sub">Kategori peminjam, identitas, dan kontak yang dapat dihubungi.</p>\n          </div>\n        </div>\n\n        <div class="form-grid">\n          <div class="field" id="field-borrower_type">\n            <label for="borrower_type">Jenis peminjam <span class="req" aria-hidden="true">*</span></label>\n            <select id="borrower_type" name="borrower_type" required data-borrower-type\n                    aria-describedby="borrower_type-hint{% if errors.get(\'borrower_type\') %} borrower_type-error{% endif %}"\n                    {% if errors.get(\'borrower_type\') %}aria-invalid="true"{% endif %}>\n              <option value="mahasiswa" {% if values[\'borrower_type\'] == \'mahasiswa\' %}selected{% endif %}>Mahasiswa</option>\n              <option value="organisasi" {% if values[\'borrower_type\'] in (\'organisasi\', \'bem\') %}selected{% endif %}>Organisasi mahasiswa</option>\n              <option value="dosen" {% if values[\'borrower_type\'] == \'dosen\' %}selected{% endif %}>Dosen</option>\n            </select>\n            <p class="hint" id="borrower_type-hint">Menentukan label identitas yang perlu diisi.</p>\n            {% if errors.get(\'borrower_type\') %}<p class="error-text" id="borrower_type-error">{{ errors[\'borrower_type\'] }}</p>{% endif %}\n          </div>\n          <div class="field" id="field-pic_name">\n            <label for="pic_name"><span data-borrower-name-label>{{ \'Nama dosen\' if values[\'borrower_type\'] == \'dosen\' else \'Nama mahasiswa\' }}</span> <span class="req" aria-hidden="true">*</span></label>\n            <input id="pic_name" name="pic_name" type="text" autocomplete="name" value="{{ values[\'pic_name\'] }}"\n                   placeholder="Nama lengkap peminjam" required\n                   aria-describedby="pic_name-hint{% if errors.get(\'pic_name\') %} pic_name-error{% endif %}"\n                   {% if errors.get(\'pic_name\') %}aria-invalid="true"{% endif %}>\n            <p class="hint" id="pic_name-hint">Nama yang dapat dihubungi admin.</p>\n            {% if errors.get(\'pic_name\') %}<p class="error-text" id="pic_name-error">{{ errors[\'pic_name\'] }}</p>{% endif %}\n          </div>\n          <div class="field" id="field-identity_number">\n            <label for="identity_number"><span data-borrower-id-label>{{ \'NIDN/NIP\' if values[\'borrower_type\'] == \'dosen\' else \'NIM\' }}</span> <span class="req" aria-hidden="true">*</span></label>\n            <input id="identity_number" name="identity_number" type="text" inputmode="numeric" value="{{ values[\'identity_number\'] }}"\n                   placeholder="{{ \'contoh: 0012345678\' if values[\'borrower_type\'] == \'dosen\' else \'contoh: 2023010101\' }}"\n                   maxlength="20" autocomplete="off" required\n                   aria-describedby="identity-hint{% if errors.get(\'identity_number\') %} identity_number-error{% endif %}"\n                   {% if errors.get(\'identity_number\') %}aria-invalid="true"{% endif %}>\n            <p class="hint" id="identity-hint" data-identity-hint>{% if values[\'borrower_type\'] == \'dosen\' %}NIDN atau NIP dosen.{% else %}NIM peminjam (organisasi mahasiswa juga memakai NIM pengurus).{% endif %}</p>\n            {% if errors.get(\'identity_number\') %}<p class="error-text" id="identity_number-error">{{ errors[\'identity_number\'] }}</p>{% endif %}\n          </div>\n          <div class="field">\n            <label for="pic_phone">Kontak peminjam <span class="req" aria-hidden="true">*</span></label>\n            <input id="pic_phone" name="pic_phone" type="tel" inputmode="tel" autocomplete="tel" value="{{ values[\'pic_phone\'] }}"\n                   placeholder="08xx xxxx xxxx" required\n                   aria-describedby="pic_phone-hint{% if errors.get(\'pic_phone\') %} pic_phone-error{% endif %}"\n                   {% if errors.get(\'pic_phone\') %}aria-invalid="true"{% endif %}>\n            <p class="hint" id="pic_phone-hint">Nomor aktif untuk koordinasi hari kegiatan.</p>\n            {% if errors.get(\'pic_phone\') %}<p class="error-text" id="pic_phone-error">{{ errors[\'pic_phone\'] }}</p>{% endif %}\n          </div>\n        </div>\n      </section>\n\n      <section class="card" aria-labelledby="when-title">\n        <div class="section-head">\n          <span class="section-number" aria-hidden="true">02</span>\n          <div>\n            <h2 id="when-title">Ruangan dan waktu</h2>\n            <p class="card-sub">Jam dalam WITA. Rentang waktu tidak boleh bertabrakan dengan pengajuan lain.</p>\n          </div>\n        </div>\n\n        <div class="field" id="field-room_id">\n          <label for="room_id">Ruangan <span class="req" aria-hidden="true">*</span></label>\n          <select id="room_id" name="room_id" required data-room-select\n                  aria-describedby="room-hint{% if errors.get(\'room_id\') %} room_id-error{% endif %}"\n                  {% if errors.get(\'room_id\') %}aria-invalid="true"{% endif %}>\n            <option value="">Pilih ruangan</option>\n            {% for building, rooms in rooms_grouped.items() %}\n              <optgroup label="{{ building }}">\n                {% for room in rooms %}\n                  <option value="{{ room[\'id\'] }}" {% if values[\'room_id\'] == room[\'id\']|string %}selected{% endif %}>\n                    {{ room[\'code\'] }} · {{ room[\'name\'] }} ({{ room[\'kind\'] }})\n                  </option>\n                {% endfor %}\n              </optgroup>\n            {% endfor %}\n            <option value="other" {% if values[\'room_id\'] == \'other\' %}selected{% endif %}>Lainnya — isi nama ruangan</option>\n          </select>\n          <p class="hint" id="room-hint">Status ketersediaan muncul otomatis setelah ruangan dipilih.</p>\n          {% if errors.get(\'room_id\') %}<p class="error-text" id="room_id-error">{{ errors[\'room_id\'] }}</p>{% endif %}\n        </div>\n\n        <div class="field" id="field-custom_room" data-custom-room {% if values[\'room_id\'] != \'other\' %}hidden{% endif %}>\n          <label for="custom_room">Nama ruangan lain <span class="req" aria-hidden="true">*</span></label>\n          <input id="custom_room" name="custom_room" type="text" value="{{ values[\'custom_room\'] }}"\n                 placeholder="contoh: Selasar Gedung C"\n                 aria-describedby="custom_room-hint{% if errors.get(\'custom_room\') %} custom_room-error{% endif %}"\n                 {% if values[\'room_id\'] != \'other\' %}disabled{% endif %}\n                 {% if errors.get(\'custom_room\') %}aria-invalid="true"{% endif %}>\n          <p class="hint" id="custom_room-hint">Ruangan di luar daftar tetap diperiksa bentrok berdasarkan nama yang sama.</p>\n          {% if errors.get(\'custom_room\') %}<p class="error-text" id="custom_room-error">{{ errors[\'custom_room\'] }}</p>{% endif %}\n        </div>\n\n        <div class="form-grid form-grid--three">\n          <div class="field" id="field-date">\n            <label for="date">Tanggal <span class="req" aria-hidden="true">*</span></label>\n            <input id="date" name="date" type="date" value="{{ values[\'date\'] }}" min="{{ min_date }}" max="{{ max_date }}" required\n                   aria-describedby="date-hint{% if errors.get(\'date\') %} date-error{% endif %}"\n                   {% if errors.get(\'date\') %}aria-invalid="true"{% endif %}>\n            <p class="hint" id="date-hint">Maksimal {{ settings[\'max_advance_days\'] }} hari ke depan.</p>\n            {% if errors.get(\'date\') %}<p class="error-text" id="date-error">{{ errors[\'date\'] }}</p>{% endif %}\n          </div>\n          <div class="field" id="field-start_time">\n            <label for="start_time">Jam mulai <span class="req" aria-hidden="true">*</span></label>\n            <input id="start_time" name="start_time" type="time" step="900" value="{{ values[\'start_time\'] }}"\n                   min="{{ settings[\'open_time\'] }}" max="{{ settings[\'close_time\'] }}" required\n                   aria-describedby="time-hint{% if errors.get(\'start_time\') %} start_time-error{% endif %}"\n                   {% if errors.get(\'start_time\') %}aria-invalid="true"{% endif %}>\n            {% if errors.get(\'start_time\') %}<p class="error-text" id="start_time-error">{{ errors[\'start_time\'] }}</p>{% endif %}\n          </div>\n          <div class="field" id="field-end_time">\n            <label for="end_time">Jam selesai <span class="req" aria-hidden="true">*</span></label>\n            <input id="end_time" name="end_time" type="time" step="900" value="{{ values[\'end_time\'] }}"\n                   min="{{ settings[\'open_time\'] }}" max="{{ settings[\'close_time\'] }}" required\n                   aria-describedby="time-hint{% if errors.get(\'end_time\') %} end_time-error{% endif %}"\n                   {% if errors.get(\'end_time\') %}aria-invalid="true"{% endif %}>\n            {% if errors.get(\'end_time\') %}<p class="error-text" id="end_time-error">{{ errors[\'end_time\'] }}</p>{% endif %}\n          </div>\n        </div>\n        <p class="hint" id="time-hint">Jam operasional {{ settings[\'open_time\']|jam }}–{{ settings[\'close_time\']|jam }} WITA · durasi {{ settings[\'min_duration_minutes\'] }} menit–{{ settings[\'max_duration_hours\'] }} jam.</p>\n\n        <div class="availability" data-availability>\n          <div class="availability-head">\n            <span class="availability-icon" aria-hidden="true">{{ icon(\'shield\', 18) }}</span>\n            <div>\n              <strong>Pemeriksaan ketersediaan</strong>\n              <p id="availability-status" data-availability-status role="status" aria-live="polite">Pilih ruangan, tanggal, dan jam untuk memeriksa bentrok.</p>\n            </div>\n          </div>\n          <div class="availability-detail" data-availability-detail></div>\n        </div>\n      </section>\n\n      <section class="card" aria-labelledby="purpose-title">\n        <div class="section-head">\n          <span class="section-number" aria-hidden="true">03</span>\n          <div>\n            <h2 id="purpose-title">Tujuan kegiatan</h2>\n            <p class="card-sub">Tuliskan kegiatan secara singkat agar admin dapat meninjau dengan cepat.</p>\n          </div>\n        </div>\n        <div class="field" id="field-purpose">\n          <label for="purpose">Deskripsi kegiatan <span class="req" aria-hidden="true">*</span></label>\n          <textarea id="purpose" name="purpose" rows="5" maxlength="500" required\n                    placeholder="contoh: Rapat kerja pengurus dan pembagian divisi kepanitiaan."\n                    aria-describedby="purpose-hint{% if errors.get(\'purpose\') %} purpose-error{% endif %}"\n                    {% if errors.get(\'purpose\') %}aria-invalid="true"{% endif %}>{{ values[\'purpose\'] }}</textarea>\n          <div class="field-foot">\n            <p class="hint" id="purpose-hint">Minimal 10 karakter. Hindari data pribadi yang tidak perlu.</p>\n            <span class="char-count" data-char-count>0/500</span>\n          </div>\n          {% if errors.get(\'purpose\') %}<p class="error-text" id="purpose-error">{{ errors[\'purpose\'] }}</p>{% endif %}\n        </div>\n      </section>\n    </div>\n\n    <aside class="form-side">\n      <section class="card card--sticky" aria-labelledby="summary-title">\n        <h2 id="summary-title">Ringkasan</h2>\n        <dl class="summary-list">\n          <div><dt>Ruangan</dt><dd data-summary-room>Belum dipilih</dd></div>\n          <div><dt>Tanggal</dt><dd data-summary-date>{{ values[\'date\']|tgl_singkat if values[\'date\'] else \'—\' }}</dd></div>\n          <div><dt>Waktu</dt><dd data-summary-time>—</dd></div>\n          <div><dt>Durasi</dt><dd data-summary-duration>—</dd></div>\n        </dl>\n        <hr class="rule">\n        <ol class="steps">\n          <li><span>1</span><p>Permohonan tercatat dengan status <strong>Menunggu persetujuan</strong>.</p></li>\n          <li><span>2</span><p>Admin memeriksa bentrok dan meninjau kegiatan.</p></li>\n          <li><span>3</span><p>Anda mendapat notifikasi saat status berubah.</p></li>\n        </ol>\n        <p class="card-note">{{ icon(\'info\', 15) }} Slot ikut tertahan selama pengajuan menunggu. Batalkan bila kegiatan batal.</p>\n        <button class="btn btn--primary btn--block" type="submit" data-submit>\n          {{ icon(\'check\', 18) }} Kirim permohonan\n        </button>\n        <p class="hint hint--center">Dengan mengirim, Anda menyatakan data kegiatan benar.</p>\n      </section>\n    </aside>\n  </div>\n</form>\n{% endblock %}\n',
    'reservations.html': '{% extends "base.html" %}\n{% from "_icons.html" import icon %}\n{% from "_ui.html" import status_for, empty_state, reservation_row %}\n{% block title %}Reservasi saya{% endblock %}\n\n{% block content %}\n<section class="page-head">\n  <div class="page-head-copy">\n    <p class="eyebrow">Riwayat organisasi</p>\n    <h1>Reservasi saya</h1>\n    <p class="page-sub">Pantau status pengajuan, keputusan admin, dan riwayat pemakaian ruangan.</p>\n  </div>\n  <div class="page-actions">\n    <a class="btn btn--primary" href="{{ url_for(\'reservation_new\') }}">{{ icon(\'plus\', 18) }} Ajukan reservasi</a>\n  </div>\n</section>\n\n<nav class="status-tabs" aria-label="Filter status reservasi">\n  {% set tabs = [\n    (\'semua\', \'Semua\'),\n    (\'pending\', \'Menunggu\'),\n    (\'approved\', \'Disetujui\'),\n    (\'completed\', \'Selesai\'),\n    (\'rejected\', \'Ditolak\'),\n    (\'cancelled\', \'Dibatalkan\')\n  ] %}\n  {% for key, label in tabs %}\n    <a href="{{ url_for(\'reservations\', status=key) }}" {% if status == key %}aria-current="page"{% endif %}>\n      {{ label }} <span class="tab-count">{{ counts[key] }}</span>\n    </a>\n  {% endfor %}\n</nav>\n\n{% if items %}\n  <section class="card card--list" aria-label="Daftar reservasi">\n    {% for item in items %}\n      {{ reservation_row(item.row, item.state) }}\n    {% endfor %}\n  </section>\n  <p class="list-foot">Menampilkan {{ items|length }} reservasi terbaru{% if status != \'semua\' %} pada filter ini{% endif %}.</p>\n{% else %}\n  {% if status == \'semua\' %}\n    {{ empty_state(\'calendar\', \'Belum ada reservasi\', \'Mulai dengan memilih ruangan dan waktu kegiatan organisasi Anda.\', url_for(\'reservation_new\'), \'Ajukan reservasi pertama\') }}\n  {% else %}\n    {{ empty_state(\'search\', \'Tidak ada reservasi di filter ini\', \'Coba lihat semua reservasi atau pilih status lain.\', url_for(\'reservations\'), \'Lihat semua reservasi\') }}\n  {% endif %}\n{% endif %}\n{% endblock %}\n',
    'room_detail.html': '{% extends "base.html" %}\n{% from "_icons.html" import icon %}\n{% from "_ui.html" import status_for, empty_state, status_badge %}\n{% block title %}{{ room[\'code\'] }} · {{ room[\'name\'] }}{% endblock %}\n\n{% block content %}\n<nav class="breadcrumb" aria-label="Breadcrumb">\n  <a href="{{ url_for(\'rooms\') }}">Ruangan</a>\n  <span aria-hidden="true">/</span>\n  <span aria-current="page">{{ room[\'code\'] }}</span>\n</nav>\n\n<section class="page-head page-head--room">\n  <div class="page-head-copy">\n    <p class="eyebrow">{{ room[\'building\'] }}{% if room[\'floor\'] %} · {{ room[\'floor\'] }}{% endif %}</p>\n    <h1>{{ room[\'name\'] }}</h1>\n    <p class="page-sub">{{ room[\'description\'] or room[\'kind\'] }}</p>\n    <div class="head-badges">\n      {{ status_for(state[\'key\']) }}\n      <span class="pill pill--quiet">{{ icon(\'door\', 15) }} {{ room[\'code\'] }}</span>\n      {% if state[\'next\'] %}\n        <span class="pill pill--quiet">{{ icon(\'clock\', 15) }} Dipesan berikutnya {{ state[\'next\'][\'start_time\']|jam }} WITA</span>\n      {% endif %}\n    </div>\n  </div>\n  {% if room[\'active\'] %}\n  <div class="page-actions">\n    <a class="btn btn--primary" href="{{ url_for(\'reservation_new\', ruangan=room[\'id\'], tanggal=selected.isoformat()) }}">\n      {{ icon(\'plus\', 18) }} Ajukan ruangan ini\n    </a>\n  </div>\n  {% endif %}\n</section>\n\n<div class="detail-grid">\n  <section class="card" aria-labelledby="schedule-title">\n    <div class="card-head card-head--wrap">\n      <div>\n        <h2 id="schedule-title">Papan jadwal</h2>\n        <p class="card-sub">{{ selected|tgl }}</p>\n      </div>\n      <div class="date-nav">\n        <a class="icon-link" href="{{ url_for(\'room_detail\', room_id=room[\'id\'], tanggal=prev_day.isoformat()) }}" aria-label="Hari sebelumnya">{{ icon(\'chevron-left\', 20) }}</a>\n        <form method="get" action="{{ url_for(\'room_detail\', room_id=room[\'id\']) }}" class="date-form">\n          <label class="sr-only" for="tanggal">Pilih tanggal jadwal</label>\n          <input id="tanggal" type="date" name="tanggal" value="{{ selected.isoformat() }}">\n          <button class="btn btn--secondary btn--sm" type="submit">Lihat</button>\n        </form>\n        <a class="icon-link" href="{{ url_for(\'room_detail\', room_id=room[\'id\'], tanggal=next_day.isoformat()) }}" aria-label="Hari berikutnya">{{ icon(\'chevron-right\', 20) }}</a>\n      </div>\n    </div>\n\n    {% if now_marker %}\n      <p class="now-note">{{ icon(\'clock\', 15) }} Sekarang {{ now_marker|jam }} WITA · jadwal diperbarui otomatis saat halaman dimuat.</p>\n    {% endif %}\n\n    <div class="schedule-board">\n      {% if board %}\n        {% for item in board %}\n          {% if item.kind == \'now\' %}\n            <div class="now-line"><span>Sekarang · {{ item.time|jam }}</span></div>\n          {% else %}\n            {% set booking = item.row %}\n            {% set tone = \'pending\' if booking[\'status\'] == \'pending\' else (\'in_use\' if selected == today and booking[\'start_time\'] <= now.strftime(\'%H:%M\') and booking[\'end_time\'] > now.strftime(\'%H:%M\') else (\'completed\' if selected < today or (selected == today and booking[\'end_time\'] <= now.strftime(\'%H:%M\')) else \'approved\')) %}\n            <article class="slot slot--{{ tone }}">\n              <div class="slot-time">\n                <strong>{{ booking[\'start_time\']|jam }}</strong>\n                <span>{{ booking[\'end_time\']|jam }}</span>\n              </div>\n              <div class="slot-card">\n                <div class="slot-top">\n                  <h3>{{ booking[\'purpose\'] }}</h3>\n                  {{ status_for(tone) }}\n                </div>\n                <p class="slot-meta">\n                  <span>{{ icon(\'users\', 14) }} {{ booking[\'organization_short\'] }}</span>\n                  <span>{{ icon(\'file\', 14) }} {{ booking[\'code\'] }}</span>\n                </p>\n              </div>\n            </article>\n          {% endif %}\n        {% endfor %}\n      {% else %}\n        {{ empty_state(\'sun\', \'Belum ada reservasi pada tanggal ini\', \'Ruangan ini masih lengang. Ajukan waktu Anda sekarang.\', url_for(\'reservation_new\', ruangan=room[\'id\'], tanggal=selected.isoformat()), \'Ajukan ruangan ini\') }}\n      {% endif %}\n    </div>\n\n    <p class="legend">\n      <span><span class="legend-dot legend-dot--success"></span> Disetujui</span>\n      <span><span class="legend-dot legend-dot--warning"></span> Menunggu</span>\n      <span><span class="legend-dot legend-dot--info"></span> Sedang digunakan</span>\n      <span><span class="legend-dot legend-dot--neutral"></span> Selesai</span>\n    </p>\n  </section>\n\n  <aside class="detail-side">\n    <section class="card" aria-labelledby="rules-title">\n      <h2 id="rules-title">Aturan pemakaian</h2>\n      <dl class="rule-list">\n        <div><dt>Jam operasional</dt><dd>{{ settings[\'open_time\']|jam }}–{{ settings[\'close_time\']|jam }} WITA</dd></div>\n        <div><dt>Jeda pergantian</dt><dd>{{ settings[\'buffer_minutes\'] }} menit</dd></div>\n        <div><dt>Durasi per pengajuan</dt><dd>{{ settings[\'min_duration_minutes\'] }} menit–{{ settings[\'max_duration_hours\'] }} jam</dd></div>\n        <div><dt>Pengajuan terjauh</dt><dd>{{ settings[\'max_advance_days\'] }} hari ke depan</dd></div>\n        <div><dt>Batas pembatalan</dt><dd>{% if settings[\'cancel_deadline_hours\'] %}H-{{ settings[\'cancel_deadline_hours\'] }} jam{% else %}Sebelum jam mulai{% endif %}</dd></div>\n      </dl>\n      <p class="card-note">{{ icon(\'info\', 15) }} Pengajuan yang menunggu tetap menahan slot sampai admin memutuskan.</p>\n    </section>\n\n    <section class="card" aria-labelledby="roominfo-title">\n      <h2 id="roominfo-title">Informasi ruangan</h2>\n      <dl class="rule-list">\n        <div><dt>Kode</dt><dd>{{ room[\'code\'] }}</dd></div>\n        <div><dt>Gedung</dt><dd>{{ room[\'building\'] }}</dd></div>\n        <div><dt>Lantai</dt><dd>{{ room[\'floor\'] or \'—\' }}</dd></div>\n        <div><dt>Jenis</dt><dd>{{ room[\'kind\'] }}</dd></div>\n        <div><dt>Status</dt><dd>{{ status_for(state[\'key\']) }}</dd></div>\n      </dl>\n    </section>\n  </aside>\n</div>\n{% endblock %}\n',
    'rooms.html': '{% extends "base.html" %}\n{% from "_icons.html" import icon %}\n{% from "_ui.html" import room_card, empty_state %}\n{% block title %}Ruangan{% endblock %}\n\n{% block content %}\n<section class="page-head">\n  <div class="page-head-copy">\n    <p class="eyebrow">Jelajahi kampus</p>\n    <h1>Daftar ruangan</h1>\n    <p class="page-sub">Lihat status ruangan saat ini, lalu buka jadwal untuk memilih waktu.</p>\n  </div>\n  <div class="page-actions">\n    <a class="btn btn--primary" href="{{ url_for(\'reservation_new\') }}">{{ icon(\'plus\', 18) }} Ajukan reservasi</a>\n  </div>\n</section>\n\n<form class="filter-bar" method="get" action="{{ url_for(\'rooms\') }}" role="search">\n  <div class="field field--inline">\n    <label for="q">Cari ruangan</label>\n    <div class="input-with-icon">\n      {{ icon(\'search\', 18) }}\n      <input id="q" name="q" type="search" value="{{ query_text }}" placeholder="Kode, nama, atau jenis ruangan">\n    </div>\n  </div>\n  <div class="field field--inline">\n    <label for="gedung">Gedung</label>\n    <select id="gedung" name="gedung">\n      <option value="">Semua gedung</option>\n      {% for item in buildings %}\n        <option value="{{ item }}" {% if item == building %}selected{% endif %}>{{ item }}</option>\n      {% endfor %}\n    </select>\n  </div>\n  <div class="filter-actions">\n    <button class="btn btn--secondary" type="submit">{{ icon(\'filter\', 17) }} Terapkan</button>\n    {% if query_text or building %}\n      <a class="text-link" href="{{ url_for(\'rooms\') }}">Bersihkan filter</a>\n    {% endif %}\n  </div>\n</form>\n\n<div class="result-line" aria-live="polite">\n  <p><strong>{{ room_states|length }}</strong> ruangan{% if building %} di {{ building }}{% endif %}{% if query_text %} untuk “{{ query_text }}”{% endif %}</p>\n  <p class="result-legend"><span class="legend-dot legend-dot--success"></span> Tersedia <span class="legend-dot legend-dot--info"></span> Sedang digunakan</p>\n</div>\n\n{% if room_states %}\n  <section aria-labelledby="rooms-results">\n    <h2 class="sr-only" id="rooms-results">Daftar ruangan</h2>\n    <div class="room-grid">\n    {% for room, state in room_states %}\n      {{ room_card(room, state) }}\n      {% endfor %}\n    </div>\n  </section>\n{% elif query_text or building %}\n  {{ empty_state(\'search\', \'Tidak ada ruangan yang cocok\', \'Coba kata kunci lain atau bersihkan filter gedung.\', url_for(\'rooms\'), \'Bersihkan filter\') }}\n{% else %}\n  {{ empty_state(\'door\', \'Belum ada ruangan\', \'Admin belum menambahkan ruangan yang dapat dipesan.\') }}\n{% endif %}\n{% endblock %}\n',
}
